package main

import (
	"encoding/json"
	"os"
	"path/filepath"
)

// Config represents the peco configuration file
type Config struct {
	Prompt             string                 `json:"Prompt" yaml:"Prompt"`
	Layout             string                 `json:"Layout" yaml:"Layout"`
	InitialFilter      string                 `json:"InitialFilter" yaml:"InitialFilter"`
	StickySelection    bool                   `json:"StickySelection" yaml:"StickySelection"`
	OnCancel           string                 `json:"OnCancel" yaml:"OnCancel"`
	FuzzyLongestSort   bool                   `json:"FuzzyLongestSort" yaml:"FuzzyLongestSort"`
	MaxScanBufferSize  int                    `json:"MaxScanBufferSize" yaml:"MaxScanBufferSize"`
	SuppressStatusMsg  bool                   `json:"SuppressStatusMsg" yaml:"SuppressStatusMsg"`
	ANSI               bool                   `json:"ANSI" yaml:"ANSI"`
	Height             string                 `json:"Height" yaml:"Height"`
	SelectionPrefix    string                 `json:"SelectionPrefix" yaml:"SelectionPrefix"`
	Keymap             map[string]interface{} `json:"Keymap" yaml:"Keymap"`
	Action             map[string][]string    `json:"Action" yaml:"Action"`
	Style              StyleConfig            `json:"Style" yaml:"Style"`
	CustomFilter       map[string]CustomFilterConfig `json:"CustomFilter" yaml:"CustomFilter"`
	SingleKeyJump      SingleKeyJumpConfig    `json:"SingleKeyJump" yaml:"SingleKeyJump"`
}

type StyleConfig struct {
	Basic          []string `json:"Basic" yaml:"Basic"`
	SavedSelection []string `json:"SavedSelection" yaml:"SavedSelection"`
	Selected       []string `json:"Selected" yaml:"Selected"`
	Query          []string `json:"Query" yaml:"Query"`
	QueryCursor    []string `json:"QueryCursor" yaml:"QueryCursor"`
	Matched        []string `json:"Matched" yaml:"Matched"`
	Prompt         []string `json:"Prompt" yaml:"Prompt"`
	Context        []string `json:"Context" yaml:"Context"`
}

type CustomFilterConfig struct {
	Cmd             string   `json:"Cmd" yaml:"Cmd"`
	Args            []string `json:"Args" yaml:"Args"`
	BufferThreshold int      `json:"BufferThreshold" yaml:"BufferThreshold"`
}

type SingleKeyJumpConfig struct {
	ShowPrefix bool `json:"ShowPrefix" yaml:"ShowPrefix"`
}

// DefaultConfig returns the default configuration
func DefaultConfig() *Config {
	return &Config{
		Prompt:            "QUERY>",
		Layout:            "top-down",
		InitialFilter:     "IgnoreCase",
		MaxScanBufferSize: 256,
		Style: StyleConfig{
			Basic:          []string{"on_default", "default"},
			SavedSelection: []string{"bold", "on_yellow", "white"},
			Selected:       []string{"underline", "on_cyan", "black"},
			Query:          []string{"yellow", "bold"},
			QueryCursor:    []string{"white", "on_red"},
			Matched:        []string{"red", "on_blue"},
			Prompt:         []string{"green", "bold"},
			Context:        []string{"bold"},
		},
	}
}

// LoadConfig loads configuration from a file
func LoadConfig(path string) (*Config, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	cfg := DefaultConfig()
	if err := json.Unmarshal(data, cfg); err != nil {
		return nil, err
	}
	return cfg, nil
}

// FindConfigFile finds the configuration file
func FindConfigFile(rcfile string) string {
	if rcfile != "" {
		return rcfile
	}

	// Check $XDG_CONFIG_HOME/peco/config.json
	if xdgHome := os.Getenv("XDG_CONFIG_HOME"); xdgHome != "" {
		for _, name := range []string{"config.json", "config.yaml"} {
			path := filepath.Join(xdgHome, "peco", name)
			if _, err := os.Stat(path); err == nil {
				return path
			}
		}
	}

	// Check $HOME/.config/peco/config.json
	if home, err := os.UserHomeDir(); err == nil {
		for _, name := range []string{"config.json", "config.yaml"} {
			path := filepath.Join(home, ".config", "peco", name)
			if _, err := os.Stat(path); err == nil {
				return path
			}
		}
	}

	// Check each dir in $XDG_CONFIG_DIRS
	if xdgDirs := os.Getenv("XDG_CONFIG_DIRS"); xdgDirs != "" {
		for _, dir := range filepath.SplitList(xdgDirs) {
			for _, name := range []string{"config.json", "config.yaml"} {
				path := filepath.Join(dir, "peco", name)
				if _, err := os.Stat(path); err == nil {
					return path
				}
			}
		}
	}

	// Check $HOME/.peco/config.json
	if home, err := os.UserHomeDir(); err == nil {
		for _, name := range []string{"config.json", "config.yaml"} {
			path := filepath.Join(home, ".peco", name)
			if _, err := os.Stat(path); err == nil {
				return path
			}
		}
	}

	return ""
}
GOEOF

