package main

import (
	"regexp"
	"strings"
	"unicode"
)

// FilterType represents the type of filter
type FilterType int

const (
	FilterIgnoreCase FilterType = iota
	FilterCaseSensitive
	FilterSmartCase
	FilterIRegexp
	FilterRegexp
	FilterFuzzy
)

// FilterNames maps filter types to names
var FilterNames = []string{
	"IgnoreCase",
	"CaseSensitive",
	"SmartCase",
	"IRegexp",
	"Regexp",
	"Fuzzy",
}

// FilterName returns the name of a filter type
func FilterName(ft FilterType) string {
	if int(ft) < len(FilterNames) {
		return FilterNames[ft]
	}
	return "Unknown"
}

// ParseFilterType parses a filter type from a string
func ParseFilterType(name string) FilterType {
	for i, n := range FilterNames {
		if strings.EqualFold(n, name) {
			return FilterType(i)
		}
	}
	return FilterIgnoreCase
}

// MatchResult represents a match result with highlighted ranges
type MatchResult struct {
	Line     string
	Ranges   [][2]int // start, end positions for highlighting
}

// Filter applies the filter to a list of lines
type Filter struct {
	Type     FilterType
}

// Match checks if a line matches the query and returns highlighted ranges
func (f *Filter) Match(line, query string) (bool, [][2]int) {
	if query == "" {
		return true, nil
	}

	terms := parseTerms(query)
	var allRanges [][2]int

	for _, term := range terms {
		matched, ranges := f.matchTerm(line, term)
		if !matched {
			return false, nil
		}
		allRanges = append(allRanges, ranges...)
	}

	return true, allRanges
}

// parseTerms splits a query into terms, handling negative terms and escaping
func parseTerms(query string) []string {
	var terms []string
	var current strings.Builder

	for i := 0; i < len(query); i++ {
		c := query[i]
		if c == '\\' && i+1 < len(query) {
			// Escape next character
			i++
			current.WriteByte(query[i])
		} else if c == ' ' {
			if current.Len() > 0 {
				terms = append(terms, current.String())
				current.Reset()
			}
		} else {
			current.WriteByte(c)
		}
	}
	if current.Len() > 0 {
		terms = append(terms, current.String())
	}
	return terms
}

// matchTerm checks if a line matches a single term
func (f *Filter) matchTerm(line, term string) (bool, [][2]int) {
	negative := false

	// Handle negative terms (prefix -)
	if len(term) > 1 && term[0] == '-' {
		negative = true
		term = term[1:]
	} else if term == "-" {
		// Literal hyphen
	}

	if term == "" {
		return true, nil
	}

	var matched bool
	var ranges [][2]int

	switch f.Type {
	case FilterIgnoreCase:
		matched, ranges = matchSubstring(line, term, true)
	case FilterCaseSensitive:
		matched, ranges = matchSubstring(line, term, false)
	case FilterSmartCase:
		// Use case-sensitive if query has uppercase, otherwise case-insensitive
		hasUpper := false
		for _, c := range term {
			if unicode.IsUpper(c) {
				hasUpper = true
				break
			}
		}
		matched, ranges = matchSubstring(line, term, !hasUpper)
	case FilterIRegexp:
		matched, ranges = matchRegexp(line, "(?i)"+term)
	case FilterRegexp:
		matched, ranges = matchRegexp(line, term)
	case FilterFuzzy:
		matched, ranges = matchFuzzy(line, term)
	}

	if negative {
		return !matched, nil
	}
	return matched, ranges
}

// matchSubstring finds substring matches and returns ranges
func matchSubstring(line, term string, ignoreCase bool) (bool, [][2]int) {
	searchLine := line
	searchTerm := term
	if ignoreCase {
		searchLine = strings.ToLower(line)
		searchTerm = strings.ToLower(term)
	}

	var ranges [][2]int
	start := 0
	for {
		idx := strings.Index(searchLine[start:], searchTerm)
		if idx < 0 {
			break
		}
		pos := start + idx
		ranges = append(ranges, [2]int{pos, pos + len(searchTerm)})
		start = pos + len(searchTerm)
		if start >= len(searchLine) {
			break
		}
	}

	return len(ranges) > 0, ranges
}

