package main

import (
	"fmt"
	"os"
	"syscall"
	"unsafe"
)

// Terminal handles low-level terminal operations
type Terminal struct {
	tty      *os.File
	oldState *termiosState
	width    int
	height   int
}

type termiosState struct {
	termios syscall.Termios
}

// OpenTerminal opens the terminal for reading/writing
func OpenTerminal() (*Terminal, error) {
	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		return nil, err
	}

	t := &Terminal{tty: tty}
	if err := t.updateSize(); err != nil {
		tty.Close()
		return nil, err
	}

	return t, nil
}

func (t *Terminal) updateSize() error {
	w, h, err := getTerminalSize(int(t.tty.Fd()))
	if err != nil {
		return err
	}
	t.width = w
	t.height = h
	return nil
}

func (t *Terminal) Width() int {
	return t.width
}

func (t *Terminal) Height() int {
	return t.height
}

func (t *Terminal) MakeRaw() error {
	var termios syscall.Termios
	if _, _, errno := syscall.Syscall(syscall.SYS_IOCTL,
		t.tty.Fd(),
		uintptr(syscall.TCGETS),
		uintptr(unsafe.Pointer(&termios))); errno != 0 {
		return errno
	}

	old := &termiosState{termios: termios}
	t.oldState = old

	// cfmakeraw equivalent
	termios.Iflag &^= syscall.IGNBRK | syscall.BRKINT | syscall.PARMRK | syscall.ISTRIP | syscall.INLCR | syscall.IGNCR | syscall.ICRNL | syscall.IXON
	termios.Oflag &^= syscall.OPOST
	termios.Lflag &^= syscall.ECHO | syscall.ECHONL | syscall.ICANON | syscall.ISIG | syscall.IEXTEN
	termios.Cflag &^= syscall.CSIZE | syscall.PARENB
	termios.Cflag |= syscall.CS8
	termios.Cc[syscall.VMIN] = 1
	termios.Cc[syscall.VTIME] = 0

	if _, _, errno := syscall.Syscall(syscall.SYS_IOCTL,
		t.tty.Fd(),
		uintptr(syscall.TCSETS),
		uintptr(unsafe.Pointer(&termios))); errno != 0 {
		return errno
	}

	return nil
}

func (t *Terminal) Restore() error {
	if t.oldState == nil {
		return nil
	}

	if _, _, errno := syscall.Syscall(syscall.SYS_IOCTL,
		t.tty.Fd(),
		uintptr(syscall.TCSETS),
		uintptr(unsafe.Pointer(&t.oldState.termios))); errno != 0 {
		return errno
	}
	t.oldState = nil
	return nil
}

func (t *Terminal) Close() error {
	t.Restore()
	return t.tty.Close()
}

func (t *Terminal) Fd() int {
	return int(t.tty.Fd())
}

func (t *Terminal) File() *os.File {
	return t.tty
}

// getTerminalSize gets the terminal dimensions
func getTerminalSize(fd int) (int, int, error) {
	type winsize struct {
		Row    uint16
		Col    uint16
		Xpixel uint16
		Ypixel uint16
	}
	ws := &winsize{}
	if _, _, errno := syscall.Syscall(syscall.SYS_IOCTL,
		uintptr(fd),
		syscall.TIOCGWINSZ,
		uintptr(unsafe.Pointer(ws))); errno != 0 {
		return 0, 0, fmt.Errorf("ioctl TIOCGWINSZ: %v", errno)
	}
	return int(ws.Col), int(ws.Row), nil
}
GOEOF

