package main

import (
	"fmt"
	"io"
	"strings"
	"unicode/utf8"
)

// Color represents terminal colors and attributes
type Color int

const (
	ColorDefault Color = iota
	ColorBlack
	ColorRed
	ColorGreen
	ColorYellow
	ColorBlue
	ColorMagenta
	ColorCyan
	ColorWhite
)

// Attribute represents text attributes
type Attribute int

const (
	AttrBold      Attribute = 1
	AttrUnderline Attribute = 4
	AttrReverse   Attribute = 7
)

// Style represents combined color and attributes
type Style struct {
	Fg      int // -1 = default, 0-7 = standard colors, 8-255 = 256color, 256+ = 24bit RGB
	Bg      int // same as Fg
	Attrs   []Attribute
	FgRGB   [3]byte
	BgRGB   [3]byte
	FgTrue  bool
	BgTrue  bool
	Fg256   bool
	Bg256   bool
	FgColor bool
	BgColor bool
}

// DefaultStyle is the default (no color) style
var DefaultStyle = Style{Fg: -1, Bg: -1}

// Screen represents the terminal screen
type Screen struct {
	term      *Terminal
	out       io.Writer
	cells     [][]Cell
	width     int
	height    int
}

// Cell represents a single character cell on screen
type Cell struct {
	Ch    rune
	Style Style
}

// NewScreen creates a new screen
func NewScreen(term *Terminal, out io.Writer) *Screen {
	w, h := term.Width(), term.Height()
	cells := make([][]Cell, h)
	for i := range cells {
		cells[i] = make([]Cell, w)
	}
	return &Screen{
		term:   term,
		out:    out,
		cells:  cells,
		width:  w,
		height: h,
	}
}

// Resize updates screen dimensions
func (s *Screen) Resize() {
	if err := s.term.updateSize(); err != nil {
		return
	}
	w, h := s.term.Width(), s.term.Height()
	s.width = w
	s.height = h
	cells := make([][]Cell, h)
	for i := range cells {
		cells[i] = make([]Cell, w)
	}
	s.cells = cells
}

// Width returns screen width
func (s *Screen) Width() int {
	return s.width
}

// Height returns screen height
func (s *Screen) Height() int {
	return s.height
}

// SetCell sets a cell at the given position
func (s *Screen) SetCell(x, y int, ch rune, style Style) {
	if y < 0 || y >= s.height || x < 0 || x >= s.width {
		return
	}
	s.cells[y][x] = Cell{Ch: ch, Style: style}
}

// SetString writes a string at position x,y with given style
// Returns next x position
func (s *Screen) SetString(x, y int, str string, style Style) int {
	for _, ch := range str {
		if x >= s.width {
			break
		}
		w := runeWidth(ch)
		if x+w > s.width {
			break
		}
		s.SetCell(x, y, ch, style)
		// Wide chars: fill next cell with space
		if w == 2 && x+1 < s.width {
			s.SetCell(x+1, y, ' ', style)
		}
		x += w
	}
	return x
}

// FillLine fills the rest of line y from x with spaces using given style
func (s *Screen) FillLine(x, y int, style Style) {
	for i := x; i < s.width; i++ {
		s.SetCell(i, y, ' ', style)
	}
}

// Flush renders the screen to terminal
func (s *Screen) Flush() {
	var buf strings.Builder

	// Move to top-left
	buf.WriteString("\033[H")

	for y := 0; y < s.height; y++ {
		// Move to beginning of line
		if y > 0 {
			buf.WriteString("\r\n")
		}

		var currentStyle Style
		currentStyle.Fg = -999 // Force first style

		for x := 0; x < s.width; x++ {
			cell := s.cells[y][x]

			if !stylesEqual(cell.Style, currentStyle) {
				buf.WriteString(styleToEscape(cell.Style))
				currentStyle = cell.Style
			}

			ch := cell.Ch
			if ch == 0 {
				ch = ' '
			}
			buf.WriteRune(ch)
		}
	}

	// Reset attributes
	buf.WriteString("\033[0m")

	fmt.Fprint(s.out, buf.String())
}

// Clear clears all cells
func (s *Screen) Clear() {
	for y := 0; y < s.height; y++ {
		for x := 0; x < s.width; x++ {
			s.cells[y][x] = Cell{Ch: ' ', Style: DefaultStyle}
		}
	}
}

// ClearLine clears a line
func (s *Screen) ClearLine(y int) {
	if y < 0 || y >= s.height {
		return
	}
	for x := 0; x < s.width; x++ {
		s.cells[y][x] = Cell{Ch: ' ', Style: DefaultStyle}
	}
}

// MoveCursor moves the cursor to x, y (1-based for terminal)
func (s *Screen) MoveCursor(x, y int) {
	fmt.Fprintf(s.out, "\033[%d;%dH", y+1, x+1)
}

// HideCursor hides the cursor
func (s *Screen) HideCursor() {
	fmt.Fprint(s.out, "\033[?25l")
}

// ShowCursor shows the cursor
func (s *Screen) ShowCursor() {
	fmt.Fprint(s.out, "\033[?25h")
}

func stylesEqual(a, b Style) bool {
	return a.Fg == b.Fg && a.Bg == b.Bg && 
		a.FgColor == b.FgColor && a.BgColor == b.BgColor &&
		len(a.Attrs) == len(b.Attrs)
}

func styleToEscape(s Style) string {
	var parts []string
	parts = append(parts, "0") // Reset

	// Attributes
	for _, attr := range s.Attrs {
		parts = append(parts, fmt.Sprintf("%d", attr))
	}

	// Foreground color
	if s.FgTrue {
		parts = append(parts, fmt.Sprintf("38;2;%d;%d;%d", s.FgRGB[0], s.FgRGB[1], s.FgRGB[2]))
	} else if s.Fg256 {
		parts = append(parts, fmt.Sprintf("38;5;%d", s.Fg))
	} else if s.FgColor && s.Fg >= 0 {
		if s.Fg < 8 {
			parts = append(parts, fmt.Sprintf("%d", 30+s.Fg))
		} else {
			parts = append(parts, fmt.Sprintf("%d", 90+s.Fg-8))
		}
	}

	// Background color
	if s.BgTrue {
		parts = append(parts, fmt.Sprintf("48;2;%d;%d;%d", s.BgRGB[0], s.BgRGB[1], s.BgRGB[2]))
	} else if s.Bg256 {
		parts = append(parts, fmt.Sprintf("48;5;%d", s.Bg))
	} else if s.BgColor && s.Bg >= 0 {
		if s.Bg < 8 {
			parts = append(parts, fmt.Sprintf("%d", 40+s.Bg))
		} else {
			parts = append(parts, fmt.Sprintf("%d", 100+s.Bg-8))
		}
	}

	return "\033[" + strings.Join(parts, ";") + "m"
}

// runeWidth returns the display width of a rune (1 or 2)
func runeWidth(r rune) int {
	if r < 0x80 {
		return 1
	}
	if r < 0x300 {
		return 1
	}
	// Simple approximation for wide characters (CJK etc.)
	if r >= 0x1100 {
		if r <= 0x115f ||
			r == 0x2329 || r == 0x232a ||
			(r >= 0x2e80 && r <= 0x303e) ||
			(r >= 0x3040 && r <= 0xa4cf) ||
			(r >= 0xa960 && r <= 0xa97f) ||
			(r >= 0xac00 && r <= 0xd7a3) ||
			(r >= 0xf900 && r <= 0xfaff) ||
			(r >= 0xfe10 && r <= 0xfe19) ||
			(r >= 0xfe30 && r <= 0xfe6f) ||
			(r >= 0xff01 && r <= 0xff60) ||
			(r >= 0xffe0 && r <= 0xffe6) ||
			(r >= 0x1b000 && r <= 0x1b001) ||
			(r >= 0x1f200 && r <= 0x1f251) ||
			(r >= 0x20000 && r <= 0x2fffd) ||
			(r >= 0x30000 && r <= 0x3fffd) {
			return 2
		}
	}
	return 1
}

// stringDisplayWidth returns the display width of a string
func stringDisplayWidth(s string) int {
	w := 0
	for _, r := range s {
		w += runeWidth(r)
	}
	return w
}

// StringDisplayLen returns the byte index into s where display width equals n
func StringByteAtDisplayWidth(s string, n int) int {
	w := 0
	for i, r := range s {
		if w >= n {
			return i
		}
		w += runeWidth(r)
	}
	return len(s)
}

// CountRunes returns the number of runes in a string
func CountRunes(s string) int {
	return utf8.RuneCountInString(s)
}
GOEOF

