	KeyMouseLeft
	KeyMouseMiddle
	KeyMouseRight
)

// Modifier flags
type Modifier int

const (
	ModNone  Modifier = 0
	ModAlt   Modifier = 1
	ModShift Modifier = 2
	ModCtrl  Modifier = 4
)

// InputReader reads key events from the terminal
type InputReader struct {
	file *os.File
	buf  []byte
}

