package main

import (
	"os"
)

// KeyEvent represents a key press event
type KeyEvent struct {
	Key  Key
	Rune rune
	Mod  Modifier
}

// Key represents a key code
type Key int

const (
	KeyNone Key = iota
	KeyEsc
	KeyEnter
	KeyBackspace
	KeyDelete
	KeyTab
	KeyInsert
	KeyHome
	KeyEnd
	KeyPgUp
	KeyPgDn
	KeyArrowUp
