	// Control keys
	KeyCtrlA
	KeyCtrlB
	KeyCtrlC
	KeyCtrlD
	KeyCtrlE
	KeyCtrlF
	KeyCtrlG
	KeyCtrlH
	KeyCtrlI // Tab
	KeyCtrlJ // Enter
	KeyCtrlK
	KeyCtrlL
	KeyCtrlM // Enter
	KeyCtrlN
	KeyCtrlO
	KeyCtrlP
	KeyCtrlQ
	KeyCtrlR
	KeyCtrlS
	KeyCtrlT
	KeyCtrlU
	KeyCtrlV
	KeyCtrlW
	KeyCtrlX
	KeyCtrlY
	KeyCtrlZ
	KeyCtrl2
	KeyCtrl3
	KeyCtrl4
	KeyCtrl5
	KeyCtrl6
	KeyCtrl7
	KeyCtrl8
	KeyCtrlBackslash
	KeyCtrlCloseBracket
	KeyCtrlCaret
	KeyCtrlUnderscore
	KeyCtrlSpace
	KeyCtrlSlash
	// Mouse
	KeyMouseLeft
	KeyMouseMiddle
	KeyMouseRight
)

// Modifier flags
type Modifier int

const (
	ModNone  Modifier = 0
	ModAlt   Modifier = 1
	ModShift Modifier = 2
	ModCtrl  Modifier = 4
)

// InputReader reads key events from the terminal
type InputReader struct {
	file *os.File
	buf  []byte
}

// NewInputReader creates a new InputReader
func NewInputReader(file *os.File) *InputReader {
	return &InputReader{
		file: file,
		buf:  make([]byte, 0, 64),
	}
}

// ReadKey reads a single key event
func (r *InputReader) ReadKey() (KeyEvent, error) {
	buf := make([]byte, 32)
	n, err := r.file.Read(buf)
	if err != nil {
		return KeyEvent{}, err
	}
	return parseKeyBytes(buf[:n]), nil
}

// parseKeyBytes converts raw bytes into a KeyEvent
func parseKeyBytes(b []byte) KeyEvent {
	if len(b) == 0 {
		return KeyEvent{}
	}

	// Handle escape sequences
	if b[0] == 0x1b {
		if len(b) == 1 {
			return KeyEvent{Key: KeyEsc}
		}
		if b[1] == '[' {
			return parseCSI(b[2:])
		}
		if b[1] == 'O' {
			return parseSS3(b[2:])
		}
		// Alt + something
		sub := parseKeyBytes(b[1:])
		sub.Mod |= ModAlt
		return sub
	}

	// Control characters
	switch b[0] {
	case 0x00:
		return KeyEvent{Key: KeyCtrlSpace}
	case 0x01:
		return KeyEvent{Key: KeyCtrlA}
	case 0x02:
		return KeyEvent{Key: KeyCtrlB}
	case 0x03:
		return KeyEvent{Key: KeyCtrlC}
	case 0x04:
		return KeyEvent{Key: KeyCtrlD}
	case 0x05:
		return KeyEvent{Key: KeyCtrlE}
	case 0x06:
		return KeyEvent{Key: KeyCtrlF}
	case 0x07:
		return KeyEvent{Key: KeyCtrlG}
	case 0x08:
		return KeyEvent{Key: KeyBackspace}
	case 0x09:
		return KeyEvent{Key: KeyTab}
	case 0x0a:
		return KeyEvent{Key: KeyCtrlJ}
	case 0x0b:
		return KeyEvent{Key: KeyCtrlK}
	case 0x0c:
		return KeyEvent{Key: KeyCtrlL}
	case 0x0d:
		return KeyEvent{Key: KeyEnter}
	case 0x0e:
		return KeyEvent{Key: KeyCtrlN}
	case 0x0f:
		return KeyEvent{Key: KeyCtrlO}
	case 0x10:
		return KeyEvent{Key: KeyCtrlP}
	case 0x11:
		return KeyEvent{Key: KeyCtrlQ}
	case 0x12:
		return KeyEvent{Key: KeyCtrlR}
	case 0x13:
		return KeyEvent{Key: KeyCtrlS}
	case 0x14:
		return KeyEvent{Key: KeyCtrlT}
	case 0x15:
		return KeyEvent{Key: KeyCtrlU}
	case 0x16:
		return KeyEvent{Key: KeyCtrlV}
	case 0x17:
		return KeyEvent{Key: KeyCtrlW}
	case 0x18:
		return KeyEvent{Key: KeyCtrlX}
	case 0x19:
		return KeyEvent{Key: KeyCtrlY}
	case 0x1a:
		return KeyEvent{Key: KeyCtrlZ}
	case 0x1c:
		return KeyEvent{Key: KeyCtrlBackslash}
	case 0x1d:
		return KeyEvent{Key: KeyCtrlCloseBracket}
	case 0x1e:
		return KeyEvent{Key: KeyCtrlCaret}
	case 0x1f:
		return KeyEvent{Key: KeyCtrlUnderscore}
	case 0x7f:
		return KeyEvent{Key: KeyBackspace}
	}

	// Regular character
	if b[0] >= 0x20 && b[0] < 0x7f {
		return KeyEvent{Key: KeyNone, Rune: rune(b[0])}
	}

	// UTF-8 character
	if b[0] >= 0x80 {
		r, _ := decodeRune(b)
		return KeyEvent{Key: KeyNone, Rune: r}
	}

	return KeyEvent{}
}

func decodeRune(b []byte) (rune, int) {
	if len(b) == 0 {
		return 0, 0
	}
	// Simple UTF-8 decoding
	if b[0] < 0x80 {
		return rune(b[0]), 1
	}
	if b[0] < 0xC0 {
		return 0xFFFD, 1
	}
	if b[0] < 0xE0 && len(b) >= 2 {
		return rune(b[0]&0x1F)<<6 | rune(b[1]&0x3F), 2
	}
	if b[0] < 0xF0 && len(b) >= 3 {
		return rune(b[0]&0x0F)<<12 | rune(b[1]&0x3F)<<6 | rune(b[2]&0x3F), 3
	}
	if len(b) >= 4 {
		return rune(b[0]&0x07)<<18 | rune(b[1]&0x3F)<<12 | rune(b[2]&0x3F)<<6 | rune(b[3]&0x3F), 4
	}
	return 0xFFFD, 1
}

// parseCSI parses CSI escape sequences (ESC [ ...)
func parseCSI(b []byte) KeyEvent {
	if len(b) == 0 {
		return KeyEvent{Key: KeyNone, Rune: '[', Mod: ModAlt}
	}

	switch b[0] {
	case 'A':
		return KeyEvent{Key: KeyArrowUp}
	case 'B':
		return KeyEvent{Key: KeyArrowDown}
	case 'C':
		return KeyEvent{Key: KeyArrowRight}
	case 'D':
		return KeyEvent{Key: KeyArrowLeft}
	case 'H':
		return KeyEvent{Key: KeyHome}
	case 'F':
		return KeyEvent{Key: KeyEnd}
	case 'Z':
		return KeyEvent{Key: KeyTab, Mod: ModShift}
	}

	// Parse numeric parameters: ESC [ N ~
	if len(b) >= 2 {
		switch {
		case b[0] == '1' && b[1] == '~':
			return KeyEvent{Key: KeyHome}
		case b[0] == '2' && b[1] == '~':
			return KeyEvent{Key: KeyInsert}
		case b[0] == '3' && b[1] == '~':
			return KeyEvent{Key: KeyDelete}
		case b[0] == '4' && b[1] == '~':
			return KeyEvent{Key: KeyEnd}
		case b[0] == '5' && b[1] == '~':
			return KeyEvent{Key: KeyPgUp}
		case b[0] == '6' && b[1] == '~':
			return KeyEvent{Key: KeyPgDn}
		}
	}

	// F keys
	if len(b) >= 2 {
		switch {
		case b[0] == '1' && b[1] == '1' && len(b) > 2 && b[2] == '~':
			return KeyEvent{Key: KeyF1}
		case b[0] == '1' && b[1] == '2' && len(b) > 2 && b[2] == '~':
			return KeyEvent{Key: KeyF2}
		case b[0] == '1' && b[1] == '5' && len(b) > 2 && b[2] == '~':
			return KeyEvent{Key: KeyF5}
		case b[0] == '1' && b[1] == '7' && len(b) > 2 && b[2] == '~':
			return KeyEvent{Key: KeyF6}
		case b[0] == '1' && b[1] == '8' && len(b) > 2 && b[2] == '~':
			return KeyEvent{Key: KeyF7}
		case b[0] == '1' && b[1] == '9' && len(b) > 2 && b[2] == '~':
			return KeyEvent{Key: KeyF8}
		case b[0] == '2' && b[1] == '0' && len(b) > 2 && b[2] == '~':
			return KeyEvent{Key: KeyF9}
		case b[0] == '2' && b[1] == '1' && len(b) > 2 && b[2] == '~':
			return KeyEvent{Key: KeyF10}
		case b[0] == '2' && b[1] == '3' && len(b) > 2 && b[2] == '~':
			return KeyEvent{Key: KeyF11}
		case b[0] == '2' && b[1] == '4' && len(b) > 2 && b[2] == '~':
			return KeyEvent{Key: KeyF12}
		}
	}

	return KeyEvent{}
}

// parseSS3 parses SS3 escape sequences (ESC O ...)
func parseSS3(b []byte) KeyEvent {
	if len(b) == 0 {
		return KeyEvent{}
	}
	switch b[0] {
	case 'A':
		return KeyEvent{Key: KeyArrowUp}
	case 'B':
		return KeyEvent{Key: KeyArrowDown}
	case 'C':
		return KeyEvent{Key: KeyArrowRight}
	case 'D':
		return KeyEvent{Key: KeyArrowLeft}
	case 'H':
		return KeyEvent{Key: KeyHome}
	case 'F':
		return KeyEvent{Key: KeyEnd}
	case 'P':
		return KeyEvent{Key: KeyF1}
	case 'Q':
		return KeyEvent{Key: KeyF2}
	case 'R':
		return KeyEvent{Key: KeyF3}
	case 'S':
		return KeyEvent{Key: KeyF4}
	}
	return KeyEvent{}
}
