package main

import (
	"fmt"
	"strconv"
	"strings"
)

// ParseStyle parses a style specification array into a Style struct
func ParseStyle(spec []string) Style {
	s := Style{Fg: -1, Bg: -1}

	for _, item := range spec {
		item = strings.ToLower(item)
		switch item {
		case "bold":
			s.Attrs = append(s.Attrs, AttrBold)
		case "underline":
			s.Attrs = append(s.Attrs, AttrUnderline)
		case "reverse":
			s.Attrs = append(s.Attrs, AttrReverse)
		case "on_bold":
			// bg bold - blink on some platforms
		case "default":
			s.FgColor = false
			s.Fg = -1
		case "on_default":
			s.BgColor = false
			s.Bg = -1
		case "black":
			s.Fg = 0
			s.FgColor = true
		case "red":
			s.Fg = 1
			s.FgColor = true
		case "green":
			s.Fg = 2
			s.FgColor = true
		case "yellow":
			s.Fg = 3
			s.FgColor = true
		case "blue":
			s.Fg = 4
			s.FgColor = true
		case "magenta":
			s.Fg = 5
			s.FgColor = true
		case "cyan":
			s.Fg = 6
			s.FgColor = true
		case "white":
			s.Fg = 7
			s.FgColor = true
		case "on_black":
			s.Bg = 0
			s.BgColor = true
		case "on_red":
			s.Bg = 1
			s.BgColor = true
		case "on_green":
			s.Bg = 2
			s.BgColor = true
		case "on_yellow":
			s.Bg = 3
			s.BgColor = true
		case "on_blue":
			s.Bg = 4
			s.BgColor = true
		case "on_magenta":
			s.Bg = 5
			s.BgColor = true
		case "on_cyan":
			s.Bg = 6
			s.BgColor = true
		case "on_white":
			s.Bg = 7
			s.BgColor = true
		default:
			// Try 256color or truecolor
			if strings.HasPrefix(item, "on_#") {
				if rgb, err := parseHexColor(item[4:]); err == nil {
					s.BgRGB = rgb
					s.BgTrue = true
					s.BgColor = true
				}
			} else if strings.HasPrefix(item, "#") {
				if rgb, err := parseHexColor(item[1:]); err == nil {
					s.FgRGB = rgb
					s.FgTrue = true
					s.FgColor = true
				}
			} else if strings.HasPrefix(item, "on_") {
				n := item[3:]
				if v, err := strconv.Atoi(n); err == nil {
					s.Bg = v
					s.Bg256 = true
					s.BgColor = true
				}
			} else {
				if v, err := strconv.Atoi(item); err == nil {
					s.Fg = v
					s.Fg256 = true
					s.FgColor = true
				}
			}
		}
	}

	return s
}

func parseHexColor(hex string) ([3]byte, error) {
	if len(hex) != 6 {
		return [3]byte{}, fmt.Errorf("invalid hex color: %s", hex)
	}
	r, err := strconv.ParseUint(hex[0:2], 16, 8)
	if err != nil {
		return [3]byte{}, err
	}
	g, err := strconv.ParseUint(hex[2:4], 16, 8)
	if err != nil {
		return [3]byte{}, err
	}
	b, err := strconv.ParseUint(hex[4:6], 16, 8)
	if err != nil {
		return [3]byte{}, err
	}
	return [3]byte{byte(r), byte(g), byte(b)}, nil
}

// StylesFromConfig creates a styles configuration from config
type Styles struct {
	Basic          Style
	SavedSelection Style
	Selected       Style
	Query          Style
	QueryCursor    Style
	Matched        Style
	Prompt         Style
	Context        Style
}

func DefaultStyles() *Styles {
	return &Styles{
		Basic:          ParseStyle([]string{"on_default", "default"}),
		SavedSelection: ParseStyle([]string{"bold", "on_yellow", "white"}),
		Selected:       ParseStyle([]string{"underline", "on_cyan", "black"}),
		Query:          ParseStyle([]string{"yellow", "bold"}),
		QueryCursor:    ParseStyle([]string{"white", "on_red"}),
		Matched:        ParseStyle([]string{"red", "on_blue"}),
		Prompt:         ParseStyle([]string{"green", "bold"}),
		Context:        ParseStyle([]string{"bold"}),
	}
}

func StylesFromConfig(cfg *StyleConfig) *Styles {
	styles := DefaultStyles()
	if len(cfg.Basic) > 0 {
		styles.Basic = ParseStyle(cfg.Basic)
	}
	if len(cfg.SavedSelection) > 0 {
		styles.SavedSelection = ParseStyle(cfg.SavedSelection)
	}
	if len(cfg.Selected) > 0 {
		styles.Selected = ParseStyle(cfg.Selected)
	}
	if len(cfg.Query) > 0 {
		styles.Query = ParseStyle(cfg.Query)
	}
	if len(cfg.QueryCursor) > 0 {
		styles.QueryCursor = ParseStyle(cfg.QueryCursor)
	}
	if len(cfg.Matched) > 0 {
		styles.Matched = ParseStyle(cfg.Matched)
	}
	if len(cfg.Prompt) > 0 {
		styles.Prompt = ParseStyle(cfg.Prompt)
	}
	if len(cfg.Context) > 0 {
		styles.Context = ParseStyle(cfg.Context)
	}
	return styles
}
