)

// Action represents a peco action
type Action string

const (
	ActionForwardChar            Action = "peco.ForwardChar"
	ActionBackwardChar           Action = "peco.BackwardChar"
	ActionForwardWord            Action = "peco.ForwardWord"
	ActionBackwardWord           Action = "peco.BackwardWord"
