	ActionScrollLeft             Action = "peco.ScrollLeft"
	ActionScrollRight            Action = "peco.ScrollRight"
	ActionScrollFirstItem        Action = "peco.ScrollFirstItem"
	ActionScrollLastItem         Action = "peco.ScrollLastItem"
	ActionToggleSelection        Action = "peco.ToggleSelection"
	ActionToggleSelectionAndSelectNext Action = "peco.ToggleSelectionAndSelectNext"
	ActionToggleSingleKeyJump    Action = "peco.ToggleSingleKeyJump"
	ActionSelectNone             Action = "peco.SelectNone"
	ActionSelectAll              Action = "peco.SelectAll"
	ActionSelectVisible          Action = "peco.SelectVisible"
	ActionToggleSelectMode       Action = "peco.ToggleSelectMode"
	ActionCancelSelectMode       Action = "peco.CancelSelectMode"
	ActionToggleRangeMode        Action = "peco.ToggleRangeMode"
	ActionCancelRangeMode        Action = "peco.CancelRangeMode"
	ActionToggleQuery            Action = "peco.ToggleQuery"
	ActionViewAround             Action = "peco.ViewAround"
	ActionGoToNextSelection      Action = "peco.GoToNextSelection"
	ActionGoToPreviousSelection  Action = "peco.GoToPreviousSelection"
	ActionRotateFilter           Action = "peco.RotateFilter"
	ActionFreezeResults          Action = "peco.FreezeResults"
	ActionUnfreezeResults        Action = "peco.UnfreezeResults"
	ActionZoomIn                 Action = "peco.ZoomIn"
	ActionZoomOut                Action = "peco.ZoomOut"
	ActionFinish                 Action = "peco.Finish"
	ActionCancel                 Action = "peco.Cancel"
)

// ActionAliases maps deprecated actions to current ones
var ActionAliases = map[Action]Action{
	"peco.SelectPreviousPage": ActionScrollPageUp,
	"peco.SelectNextPage":     ActionScrollPageDown,
	"peco.SelectPrevious":     ActionSelectUp,
	"peco.SelectNext":         ActionSelectDown,
	"peco.ToggleSelectMode":   ActionToggleRangeMode,
	"peco.CancelSelectMode":   ActionCancelRangeMode,
}

// KeyBinding maps key sequences to actions
type KeyBinding struct {
	keys   []KeySpec
	action Action
}

// KeySpec identifies a key
type KeySpec struct {
	Key Key
	Mod Modifier
	Ch  rune
}

// Keymap holds all key bindings
type Keymap struct {
	bindings    []KeyBinding
	customActions map[Action][]Action
	// For sequence support
	pendingKeys []KeySpec
}

// DefaultKeymap returns the default key bindings
func DefaultKeymap() *Keymap {
	km := &Keymap{}

	defaults := []struct {
		key    string
		action Action
	}{
		{"Esc", ActionCancel},
		{"C-c", ActionCancel},
		{"Enter", ActionFinish},
		{"C-f", ActionForwardChar},
		{"C-a", ActionBeginningOfLine},
		{"C-b", ActionBackwardChar},
		{"C-d", ActionDeleteForwardChar},
		{"C-e", ActionEndOfLine},
		{"C-k", ActionKillEndOfLine},
		{"C-u", ActionKillBeginningOfLine},
		{"BS", ActionDeleteBackwardChar},
		{"C-8", ActionDeleteBackwardChar},
		{"C-w", ActionDeleteBackwardWord},
		{"C-g", ActionSelectNone},
		{"C-n", ActionSelectDown},
		{"C-p", ActionSelectUp},
		{"C-r", ActionRotateFilter},
		{"C-t", ActionToggleQuery},
		{"C-Space", ActionToggleSelectionAndSelectNext},
		{"ArrowUp", ActionSelectUp},
		{"ArrowDown", ActionSelectDown},
		{"ArrowLeft", ActionScrollPageUp},
		{"ArrowRight", ActionScrollPageDown},
		{"Pgup", ActionScrollPageUp},
		{"Pgdn", ActionScrollPageDown},
	}

	for _, d := range defaults {
		km.SetBinding(d.key, d.action)
	}

	return km
}

// SetBinding sets a key binding
func (km *Keymap) SetBinding(keyStr string, action Action) {
	specs := parseKeyString(keyStr)
	if len(specs) == 0 {
		return
	}

	// Resolve aliases
	if aliased, ok := ActionAliases[action]; ok {
		action = aliased
	}

	// Remove existing binding for this key sequence
	for i, b := range km.bindings {
		if keySpecsEqual(b.keys, specs) {
			km.bindings = append(km.bindings[:i], km.bindings[i+1:]...)
			break
		}
	}

	km.bindings = append(km.bindings, KeyBinding{
		keys:   specs,
		action: action,
	})
}

// SetCustomAction sets a custom combined action
func (km *Keymap) SetCustomAction(name string, actions []string) {
	if km.customActions == nil {
		km.customActions = make(map[Action][]Action)
	}
	var actionList []Action
	for _, a := range actions {
		actionList = append(actionList, Action(a))
	}
	km.customActions[Action(name)] = actionList
}

// LookupAction looks up an action for the given key event
// Returns the action and whether it's a prefix match
func (km *Keymap) LookupAction(event KeyEvent) (Action, bool, bool) {
	spec := keyEventToSpec(event)

	newPending := append(km.pendingKeys, spec)

	var exactMatch Action
	hasPrefix := false
	hasExact := false

	for _, b := range km.bindings {
		if len(b.keys) < len(newPending) {
			continue
		}
		if keySpecsMatch(b.keys[:len(newPending)], newPending) {
			if len(b.keys) == len(newPending) {
				exactMatch = b.action
				hasExact = true
			} else {
				hasPrefix = true
			}
		}
	}

	if hasExact {
		km.pendingKeys = nil
		return exactMatch, true, false
	}
	if hasPrefix {
		km.pendingKeys = newPending
		return "", false, true
	}

	// No match - clear pending and return no action
	km.pendingKeys = nil
	return "", false, false
}

func keySpecsEqual(a, b []KeySpec) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func keySpecsMatch(a, b []KeySpec) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func keyEventToSpec(e KeyEvent) KeySpec {
	return KeySpec{
		Key: e.Key,
		Mod: e.Mod,
		Ch:  e.Rune,
	}
}

// parseKeyString parses a key string like "C-a", "M-v", "Enter", etc.
func parseKeyString(s string) []KeySpec {
	// Handle sequences with comma
	parts := strings.Split(s, ",")
	var specs []KeySpec
	for _, p := range parts {
		p = strings.TrimSpace(p)
		spec, err := parseSingleKey(p)
		if err != nil {
			return nil
		}
		specs = append(specs, spec)
	}
	return specs
}

func parseSingleKey(s string) (KeySpec, error) {
	var mod Modifier

	// Strip modifiers
	for {
		if strings.HasPrefix(s, "M-") {
			mod |= ModAlt
			s = s[2:]
		} else if strings.HasPrefix(s, "C-") {
			s = s[2:]
			// Will be handled below
			return parseCtrlKey(s, mod)
		} else if strings.HasPrefix(s, "S-") {
			mod |= ModShift
			s = s[2:]
		} else {
			break
		}
	}

	return parseNamedKey(s, mod)
}

func parseCtrlKey(s string, mod Modifier) (KeySpec, error) {
	mod |= ModCtrl
	switch strings.ToLower(s) {
	case "space":
		return KeySpec{Key: KeyCtrlSpace, Mod: mod}, nil
	case "a":
		return KeySpec{Key: KeyCtrlA, Mod: mod}, nil
	case "b":
		return KeySpec{Key: KeyCtrlB, Mod: mod}, nil
	case "c":
		return KeySpec{Key: KeyCtrlC, Mod: mod}, nil
	case "d":
		return KeySpec{Key: KeyCtrlD, Mod: mod}, nil
	case "e":
		return KeySpec{Key: KeyCtrlE, Mod: mod}, nil
	case "f":
		return KeySpec{Key: KeyCtrlF, Mod: mod}, nil
	case "g":
		return KeySpec{Key: KeyCtrlG, Mod: mod}, nil
	case "h":
		return KeySpec{Key: KeyCtrlH, Mod: mod}, nil
	case "i":
		return KeySpec{Key: KeyCtrlI, Mod: mod}, nil
	case "j":
		return KeySpec{Key: KeyCtrlJ, Mod: mod}, nil
	case "k":
		return KeySpec{Key: KeyCtrlK, Mod: mod}, nil
	case "l":
		return KeySpec{Key: KeyCtrlL, Mod: mod}, nil
	case "m":
		return KeySpec{Key: KeyCtrlM, Mod: mod}, nil
	case "n":
		return KeySpec{Key: KeyCtrlN, Mod: mod}, nil
	case "o":
		return KeySpec{Key: KeyCtrlO, Mod: mod}, nil
	case "p":
		return KeySpec{Key: KeyCtrlP, Mod: mod}, nil
	case "q":
		return KeySpec{Key: KeyCtrlQ, Mod: mod}, nil
	case "r":
		return KeySpec{Key: KeyCtrlR, Mod: mod}, nil
	case "s":
		return KeySpec{Key: KeyCtrlS, Mod: mod}, nil
	case "t":
		return KeySpec{Key: KeyCtrlT, Mod: mod}, nil
	case "u":
		return KeySpec{Key: KeyCtrlU, Mod: mod}, nil
	case "v":
		return KeySpec{Key: KeyCtrlV, Mod: mod}, nil
	case "w":
		return KeySpec{Key: KeyCtrlW, Mod: mod}, nil
	case "x":
		return KeySpec{Key: KeyCtrlX, Mod: mod}, nil
	case "y":
		return KeySpec{Key: KeyCtrlY, Mod: mod}, nil
	case "z":
		return KeySpec{Key: KeyCtrlZ, Mod: mod}, nil
	case "2":
		return KeySpec{Key: KeyCtrl2, Mod: mod}, nil
	case "3":
		return KeySpec{Key: KeyCtrl3, Mod: mod}, nil
	case "4":
		return KeySpec{Key: KeyCtrl4, Mod: mod}, nil
	case "5":
		return KeySpec{Key: KeyCtrl5, Mod: mod}, nil
	case "6":
		return KeySpec{Key: KeyCtrl6, Mod: mod}, nil
	case "7":
		return KeySpec{Key: KeyCtrl7, Mod: mod}, nil
	case "8":
		return KeySpec{Key: KeyCtrl8, Mod: mod}, nil
	case "[":
		return KeySpec{Key: KeyCtrlCloseBracket, Mod: mod}, nil
	case "]":
		return KeySpec{Key: KeyCtrlCloseBracket, Mod: mod}, nil
	case "\\":
		return KeySpec{Key: KeyCtrlBackslash, Mod: mod}, nil
	case "~":
		return KeySpec{Key: KeyCtrlCaret, Mod: mod}, nil
	case "_":
		return KeySpec{Key: KeyCtrlUnderscore, Mod: mod}, nil
	case "/":
		return KeySpec{Key: KeyCtrlSlash, Mod: mod}, nil
	// Navigation keys with ctrl
	case "arrowleft":
		return KeySpec{Key: KeyArrowLeft, Mod: mod}, nil
	case "arrowright":
		return KeySpec{Key: KeyArrowRight, Mod: mod}, nil
	case "arrowup":
		return KeySpec{Key: KeyArrowUp, Mod: mod}, nil
	case "arrowdown":
		return KeySpec{Key: KeyArrowDown, Mod: mod}, nil
	case "delete":
		return KeySpec{Key: KeyDelete, Mod: mod}, nil
	}
	return KeySpec{}, fmt.Errorf("unknown ctrl key: %s", s)
}

func parseNamedKey(s string, mod Modifier) (KeySpec, error) {
	switch strings.ToLower(s) {
	case "esc":
		return KeySpec{Key: KeyEsc, Mod: mod}, nil
	case "enter":
		return KeySpec{Key: KeyEnter, Mod: mod}, nil
	case "tab":
		return KeySpec{Key: KeyTab, Mod: mod}, nil
	case "bs", "backspace":
		return KeySpec{Key: KeyBackspace, Mod: mod}, nil
	case "bs2":
		return KeySpec{Key: KeyBackspace, Mod: mod}, nil
	case "delete":
