func parseColorPart(s string) int {
	n := 0
	for _, c := range s {
		if c >= '0' && c <= '9' {
			n = n*10 + int(c-'0')
		}
	}
	return n
}

func appendAttr(attrs []Attribute, attr Attribute) []Attribute {
	for _, a := range attrs {
		if a == attr {
			return attrs
		}
	}
	return append(attrs, attr)
}
