func (p *Peco) applyOptions() {
	opts := p.opts

	if opts.Prompt != "" {
		p.config.Prompt = opts.Prompt
	}

	if opts.Layout != "" {
		p.config.Layout = opts.Layout
	}

	if opts.InitialFilter != "" {
		p.config.InitialFilter = opts.InitialFilter
	}

	if opts.OnCancel != "" {
		p.config.OnCancel = opts.OnCancel
	}

	if opts.SelectionPrefix != "" {
		p.config.SelectionPrefix = opts.SelectionPrefix
	}

	if opts.Exec != "" {
		p.execCmd = opts.Exec
	}

	if opts.ANSI {
		p.config.ANSI = true
	}
}

func (p *Peco) parseHeight() {
	height := p.opts.Height
	if height == "" {
		height = p.config.Height
	}
	if height == "" {
		return
	}

	if strings.HasSuffix(height, "%") {
		pct, err := strconv.ParseFloat(height[:len(height)-1], 64)
		if err == nil {
			p.heightPct = pct / 100.0
			p.heightIsPercent = true
		}
	} else {
		n, err := strconv.Atoi(height)
		if err == nil {
			p.heightLines = n
		}
	}
}

func (p *Peco) readInput() error {
	var reader io.Reader

	if p.opts.File != "" {
		f, err := os.Open(p.opts.File)
		if err != nil {
			return fmt.Errorf("failed to open file: %v", err)
		}
		defer f.Close()
		reader = f
	} else {
		reader = os.Stdin
	}

	scanner := bufio.NewScanner(reader)
	bufSize := p.config.MaxScanBufferSize * 1024
	if bufSize < 64*1024 {
		bufSize = 64 * 1024
	}
	buf := make([]byte, bufSize)
	scanner.Buffer(buf, bufSize)

	if p.opts.Null {
		// NUL-separated mode
		scanner.Split(splitOnNul)
	}

	bufferSize := p.opts.BufferSize

	for scanner.Scan() {
		line := scanner.Text()
		p.lines = append(p.lines, line)
		if bufferSize > 0 && len(p.lines) >= bufferSize {
			// Keep only the last bufferSize lines by sliding window
			p.lines = p.lines[len(p.lines)-bufferSize:]
		}
	}

	return nil
}

// splitOnNul is a custom split function for NUL-separated input
func splitOnNul(data []byte, atEOF bool) (advance int, token []byte, err error) {
	for i, b := range data {
		if b == 0 {
			return i + 1, data[:i], nil
		}
	}
	if atEOF && len(data) > 0 {
		return len(data), data, nil
	}
	return 0, nil, nil
}

func (p *Peco) selectAllAndExit() error {
	for _, line := range p.lines {
		fmt.Println(line)
	}
	return nil
}

func (p *Peco) initScreen() (*Terminal, error) {
	term, err := OpenTerminal()
	if err != nil {
		return nil, fmt.Errorf("failed to initialize screen: failed to initialize tcell screen: %v", err)
	}

	// Check TERM environment variable
	termEnv := os.Getenv("TERM")
	if termEnv == "" {
		term.Close()
		return nil, fmt.Errorf("failed to initialize screen: failed to create tcell screen: terminal entry not found: term not set")
	}

	if termEnv == "dumb" {
		term.Close()
		return nil, fmt.Errorf("failed to initialize screen: failed to create tcell screen: terminal not cursor addressable")
	}

	if err := term.MakeRaw(); err != nil {
		term.Close()
		return nil, fmt.Errorf("failed to initialize screen: %v", err)
	}

	p.screen = NewScreen(term, term.File())
	p.inputReader = NewInputReader(term.File())

	return term, nil
}

func (p *Peco) applyInitialFilter() {
	p.filteredLines = p.computeFilter()
}

func (p *Peco) computeFilter() []int {
	query := string(p.query)

	// If query is disabled, return all lines
	if !p.queryEnabled || query == "" {
		result := make([]int, len(p.lines))
		for i := range p.lines {
			result[i] = i
		}
		return result
	}

	var result []int
	for i, line := range p.lines {
		displayLine := line
		if p.config.ANSI {
			displayLine = StripANSI(line)
		}
		if matched, _ := p.filter.Match(displayLine, query); matched {
			result = append(result, i)
		}
	}
	if result == nil {
		result = []int{}
	}
	return result
}

func (p *Peco) mainLoop() error {
	// Set up signal handler for SIGWINCH (terminal resize)
	sigCh := make(chan os.Signal, 1)
	signal.Notify(sigCh, syscall.SIGWINCH)
	defer signal.Stop(sigCh)

	// Set up input channel
	keyCh := make(chan KeyEvent, 10)
	errCh := make(chan error, 1)

	go func() {
		for {
			ev, err := p.inputReader.ReadKey()
			if err != nil {
				errCh <- err
				return
			}
			keyCh <- ev
		}
	}()

	// Initial render
	p.render()

	for {
		select {
		case <-sigCh:
			// Terminal resized
			p.screen.Resize()
			p.adjustPageOffset()
			p.render()

		case err := <-errCh:
			return p.handleExit(false, err)

		case ev := <-keyCh:
			done, err := p.handleKey(ev)
			if done {
				return err
			}
		}
	}
}

func (p *Peco) handleKey(ev KeyEvent) (bool, error) {
	action, found, isPending := p.keymap.LookupAction(ev)

	if isPending {
		// Waiting for more keys in sequence
		return false, nil
	}

	if !found {
		// Check if it's a regular character to type
		if ev.Key == KeyNone && ev.Rune != 0 && ev.Mod == ModNone {
			p.insertChar(ev.Rune)
			p.onQueryChange()
			p.render()
			return false, nil
		}
		if ev.Key == KeyNone && ev.Rune != 0 && ev.Mod == ModAlt {
			// Alt+char - treat as regular input or ignore
			return false, nil
		}
		return false, nil
	}

	return p.executeAction(action)
}

func (p *Peco) executeAction(action Action) (bool, error) {
	// Resolve custom actions
	if p.keymap.customActions != nil {
		if actions, ok := p.keymap.customActions[action]; ok {
			for _, a := range actions {
				done, err := p.executeAction(a)
				if done {
					return done, err
				}
			}
			return false, nil
		}
	}

	switch action {
	case ActionCancel:
		if p.rangeModeActive {
			p.rangeModeActive = false
			p.render()
			return false, nil
		}
		return p.handleExit(false, nil), nil

	case ActionFinish:
		return p.handleExit(true, nil), nil

	case ActionForwardChar:
		if p.queryCursor < len(p.query) {
			p.queryCursor++
			p.render()
		}

	case ActionBackwardChar:
		if p.queryCursor > 0 {
			p.queryCursor--
			p.render()
		}

	case ActionForwardWord:
		p.moveWordForward()
		p.render()

	case ActionBackwardWord:
		p.moveWordBackward()
		p.render()

	case ActionBeginningOfLine:
		p.queryCursor = 0
		p.render()

	case ActionEndOfLine:
		p.queryCursor = len(p.query)
		p.render()

	case ActionEndOfFile:
		if len(p.query) == 0 {
			return p.handleExit(false, nil), nil
		}
		p.deleteForwardChar()
		p.onQueryChange()
		p.render()

	case ActionDeleteForwardChar:
		p.deleteForwardChar()
		p.onQueryChange()
		p.render()

	case ActionDeleteBackwardChar:
		p.deleteBackwardChar()
		p.onQueryChange()
		p.render()

	case ActionDeleteForwardWord:
		p.deleteForwardWord()
		p.onQueryChange()
		p.render()

	case ActionDeleteBackwardWord:
		p.deleteBackwardWord()
		p.onQueryChange()
		p.render()

	case ActionKillEndOfLine:
		if p.queryCursor <= len(p.query) {
			p.query = p.query[:p.queryCursor]
			p.onQueryChange()
			p.render()
		}

	case ActionKillBeginningOfLine:
		if p.queryCursor > 0 {
			p.query = p.query[p.queryCursor:]
			p.queryCursor = 0
			p.onQueryChange()
			p.render()
		}

	case ActionDeleteAll:
		p.query = nil
		p.queryCursor = 0
		p.onQueryChange()
		p.render()

	case ActionSelectUp:
		if p.rangeModeActive {
			p.extendRangeUp()
		} else {
			p.moveUp()
		}
		p.render()

	case ActionSelectDown:
		if p.rangeModeActive {
			p.extendRangeDown()
		} else {
			p.moveDown()
		}
		p.render()

	case ActionScrollPageUp:
		p.pageUp()
		p.render()

	case ActionScrollPageDown:
		p.pageDown()
		p.render()

	case ActionScrollFirstItem:
		p.currentLine = 0
		p.pageOffset = 0
		p.render()

	case ActionScrollLastItem:
		if len(p.filteredLines) > 0 {
			p.currentLine = len(p.filteredLines) - 1
			p.adjustPageOffset()
			p.render()
		}

	case ActionScrollLeft:
		if p.hScrollOffset > 0 {
			p.hScrollOffset -= 10
			if p.hScrollOffset < 0 {
				p.hScrollOffset = 0
			}
			p.render()
		}

	case ActionScrollRight:
		p.hScrollOffset += 10
		p.render()

	case ActionToggleSelection:
		p.toggleCurrentSelection()
		p.render()

	case ActionToggleSelectionAndSelectNext:
		p.toggleCurrentSelection()
		p.moveDown()
		p.render()

	case ActionSelectNone:
		p.selectedLines = make(map[int]bool)
		p.render()

	case ActionSelectAll:
		for _, idx := range p.filteredLines {
			p.selectedLines[idx] = true
		}
		p.render()

	case ActionSelectVisible:
		visibleLines := p.getVisibleLines()
		for _, idx := range visibleLines {
			p.selectedLines[idx] = true
		}
		p.render()

	case ActionInvertSelection:
		newSelected := make(map[int]bool)
		for _, idx := range p.filteredLines {
			if !p.selectedLines[idx] {
				newSelected[idx] = true
			}
		}
		p.selectedLines = newSelected
		p.render()

	case ActionGoToNextSelection:
		p.goToNextSelection(1)
		p.render()

	case ActionGoToPreviousSelection:
		p.goToNextSelection(-1)
		p.render()

	case ActionToggleRangeMode:
		if p.rangeModeActive {
			// Finalize range selection
			p.finalizeRange()
			p.rangeModeActive = false
		} else {
			p.rangeModeActive = true
			p.rangeStart = p.currentLine
		}
		p.render()

	case ActionCancelRangeMode:
		p.rangeModeActive = false
		// Clear range selections? No, just exit range mode
		p.render()

	case ActionRotateFilter:
		p.filterType = (p.filterType + 1) % FilterType(len(FilterNames))
		p.filter = &Filter{Type: p.filterType}
		p.onQueryChange()
		p.render()

	case ActionBackToInitialFilter:
		p.filterType = FilterIgnoreCase
		p.filter = &Filter{Type: p.filterType}
		p.onQueryChange()
		p.render()

	case ActionToggleQuery:
		p.queryEnabled = !p.queryEnabled
		p.onQueryChange()
		p.render()

	case ActionFreezeResults:
		p.freezeResults()
		p.render()

	case ActionUnfreezeResults:
		p.unfreezeResults()
		p.render()

	case ActionZoomIn:
		if !p.zoomedIn {
			p.zoomedIn = true
			p.contextLines = 3
		}
		p.render()

	case ActionZoomOut:
		p.zoomedIn = false
		p.contextLines = 0
		p.render()

	case ActionViewAround:
		p.zoomedIn = !p.zoomedIn
		if p.zoomedIn {
			p.contextLines = 3
		} else {
			p.contextLines = 0
		}
		p.render()

	case ActionToggleSingleKeyJump:
		p.singleKeyJumpMode = !p.singleKeyJumpMode
		p.render()

	case ActionRefreshScreen:
		p.onQueryChange()
		p.render()
	}

	return false, nil
}

func (p *Peco) handleExit(success bool, err error) (bool, error) {
	p.cleanup()

	if !success {
		// User cancelled
		if p.config.OnCancel == "error" {
			os.Exit(1)
		}
		// Default: success exit (exit 0 on cancel)
		return true, nil
	}

	// User finished - output selections
	selections := p.getSelections()

	if p.execCmd != "" {
		return p.executeExec(selections), nil
	}

	p.outputSelections(selections)
	return true, err
}

func (p *Peco) outputSelections(selections []string) {
	if p.opts.PrintQuery {
		fmt.Println(string(p.query))
	}
	for _, line := range selections {
		fmt.Println(line)
	}
}

func (p *Peco) executeExec(selections []string) bool {
	// Write selections to a temp file or pipe
	cmd := exec.Command("/bin/sh", "-c", p.execCmd)

	// Connect stdin with selections
	stdin, err := cmd.StdinPipe()
	if err != nil {
		return false
	}

	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr

	if err := cmd.Start(); err != nil {
		return false
	}

	for _, line := range selections {
		fmt.Fprintln(stdin, line)
	}
	stdin.Close()

	cmd.Wait()

	// Don't exit - return to peco
	return false
}

func (p *Peco) getSelections() []string {
	var result []string

	if len(p.selectedLines) > 0 {
		// Return in original order
		for i, line := range p.lines {
			if p.selectedLines[i] {
				if p.opts.Null {
					// In null mode, extract display part (before NUL) and result part (after NUL)
					result = append(result, line)
				} else {
					result = append(result, line)
				}
			}
		}
	} else {
		// Return current line
		if len(p.filteredLines) > 0 && p.currentLine < len(p.filteredLines) {
			idx := p.filteredLines[p.currentLine]
			result = append(result, p.lines[idx])
		}
	}

	return result
}

func (p *Peco) cleanup() {
	if p.screen != nil && p.term != nil {
		// Clear the peco interface
		p.clearScreen()
	}
}

func (p *Peco) clearScreen() {
	if p.heightLines > 0 || p.heightIsPercent {
		// Inline mode: clear the inline area
		h := p.getDisplayHeight()
		fmt.Fprint(p.term.File(), "\033[?25h") // Show cursor
		// Move up h lines and clear
		for i := 0; i < h; i++ {
			fmt.Fprint(p.term.File(), "\033[K\033[A")
		}
		fmt.Fprint(p.term.File(), "\033[K")
	} else {
		// Full screen: just clear and go home
		fmt.Fprint(p.term.File(), "\033[2J\033[H\033[?25h")
	}
}

func (p *Peco) getDisplayHeight() int {
	totalHeight := p.term.Height()

	if p.heightLines > 0 {
		return p.heightLines + 2 // +2 for query line and status line
	}
	if p.heightIsPercent {
		h := int(float64(totalHeight) * p.heightPct)
		if h < 3 {
			h = 3
		}
		return h
	}
	return totalHeight
}

func (p *Peco) getListHeight() int {
	return p.getDisplayHeight() - 2 // subtract query line and status line
}

func (p *Peco) onQueryChange() {
	p.filteredLines = p.computeFilter()
	if p.currentLine >= len(p.filteredLines) {
		if len(p.filteredLines) > 0 {
			p.currentLine = len(p.filteredLines) - 1
		} else {
			p.currentLine = 0
		}
	}
	p.adjustPageOffset()
}

func (p *Peco) adjustPageOffset() {
	listH := p.getListHeight()
	if listH <= 0 {
		listH = 1
	}

	if p.currentLine < p.pageOffset {
		p.pageOffset = p.currentLine
	}
	if p.currentLine >= p.pageOffset+listH {
		p.pageOffset = p.currentLine - listH + 1
	}
	if p.pageOffset < 0 {
		p.pageOffset = 0
	}
}

func (p *Peco) moveUp() {
	if p.currentLine > 0 {
		p.currentLine--
		p.adjustPageOffset()
	}
}

func (p *Peco) moveDown() {
	if p.currentLine < len(p.filteredLines)-1 {
		p.currentLine++
		p.adjustPageOffset()
	}
}

func (p *Peco) pageUp() {
	listH := p.getListHeight()
	if listH <= 0 {
		listH = 1
	}

	p.currentLine -= listH
	if p.currentLine < 0 {
		p.currentLine = 0
	}
	p.pageOffset -= listH
	if p.pageOffset < 0 {
		p.pageOffset = 0
	}
	p.adjustPageOffset()
}

func (p *Peco) pageDown() {
	listH := p.getListHeight()
	if listH <= 0 {
		listH = 1
	}

	p.currentLine += listH
	if p.currentLine >= len(p.filteredLines) {
		if len(p.filteredLines) > 0 {
			p.currentLine = len(p.filteredLines) - 1
		} else {
			p.currentLine = 0
		}
	}
	p.adjustPageOffset()
}

func (p *Peco) extendRangeUp() {
	if p.currentLine > 0 {
		p.currentLine--
		p.adjustPageOffset()
		p.updateRangeSelection()
	}
}

func (p *Peco) extendRangeDown() {
	if p.currentLine < len(p.filteredLines)-1 {
		p.currentLine++
		p.adjustPageOffset()
		p.updateRangeSelection()
	}
}

func (p *Peco) updateRangeSelection() {
	// Clear previous range selections and re-apply
	start := p.rangeStart
	end := p.currentLine
	if start > end {
		start, end = end, start
	}
	for i := start; i <= end && i < len(p.filteredLines); i++ {
		p.selectedLines[p.filteredLines[i]] = true
	}
}

func (p *Peco) finalizeRange() {
	p.updateRangeSelection()
}

func (p *Peco) toggleCurrentSelection() {
	if len(p.filteredLines) == 0 {
		return
	}
	idx := p.filteredLines[p.currentLine]
	if p.selectedLines[idx] {
		delete(p.selectedLines, idx)
	} else {
		p.selectedLines[idx] = true
	}
}

func (p *Peco) goToNextSelection(dir int) {
	if len(p.filteredLines) == 0 {
		return
	}

	start := p.currentLine
	n := len(p.filteredLines)

	for i := 1; i < n; i++ {
		next := (start + dir*i + n) % n
		if p.selectedLines[p.filteredLines[next]] {
			p.currentLine = next
			p.adjustPageOffset()
			return
		}
	}
}

func (p *Peco) getVisibleLines() []int {
	listH := p.getListHeight()
	end := p.pageOffset + listH
	if end > len(p.filteredLines) {
		end = len(p.filteredLines)
	}
	var result []int
	for i := p.pageOffset; i < end; i++ {
		result = append(result, p.filteredLines[i])
	}
	return result
}

func (p *Peco) insertChar(ch rune) {
	p.query = append(p.query, 0)
	copy(p.query[p.queryCursor+1:], p.query[p.queryCursor:])
	p.query[p.queryCursor] = ch
	p.queryCursor++
}

func (p *Peco) deleteForwardChar() {
	if p.queryCursor < len(p.query) {
		p.query = append(p.query[:p.queryCursor], p.query[p.queryCursor+1:]...)
	}
}

func (p *Peco) deleteBackwardChar() {
	if p.queryCursor > 0 {
		p.query = append(p.query[:p.queryCursor-1], p.query[p.queryCursor:]...)
		p.queryCursor--
	}
}

func (p *Peco) deleteForwardWord() {
	if p.queryCursor >= len(p.query) {
		return
	}
	end := p.queryCursor
	// Skip spaces
	for end < len(p.query) && p.query[end] == ' ' {
		end++
	}
	// Skip non-spaces
	for end < len(p.query) && p.query[end] != ' ' {
		end++
	}
	p.query = append(p.query[:p.queryCursor], p.query[end:]...)
}

func (p *Peco) deleteBackwardWord() {
	if p.queryCursor <= 0 {
		return
	}
	start := p.queryCursor
	// Skip spaces
	for start > 0 && p.query[start-1] == ' ' {
		start--
	}
	// Skip non-spaces
	for start > 0 && p.query[start-1] != ' ' {
		start--
	}
	p.query = append(p.query[:start], p.query[p.queryCursor:]...)
	p.queryCursor = start
}

func (p *Peco) moveWordForward() {
	// Skip spaces
	for p.queryCursor < len(p.query) && p.query[p.queryCursor] == ' ' {
		p.queryCursor++
	}
	// Skip non-spaces
	for p.queryCursor < len(p.query) && p.query[p.queryCursor] != ' ' {
		p.queryCursor++
	}
}

func (p *Peco) moveWordBackward() {
	if p.queryCursor <= 0 {
		return
	}
	// Skip spaces
	for p.queryCursor > 0 && p.query[p.queryCursor-1] == ' ' {
		p.queryCursor--
	}
	// Skip non-spaces
	for p.queryCursor > 0 && p.query[p.queryCursor-1] != ' ' {
		p.queryCursor--
	}
}

func (p *Peco) freezeResults() {
	if !p.frozen {
		// Freeze current results
		p.frozenLines = make([]string, len(p.filteredLines))
		for i, idx := range p.filteredLines {
			p.frozenLines[i] = p.lines[idx]
		}
		p.frozen = true
	}
	// Clear query
	p.query = nil
	p.queryCursor = 0

	// Reload from frozen lines
	if p.frozen {
		// Replace lines with frozen lines and recompute
		savedLines := p.lines
		_ = savedLines
		p.lines = p.frozenLines
		p.filteredLines = p.computeFilter()
	}
}

func (p *Peco) unfreezeResults() {
	if p.frozen {
		// Note: we'd need to save original lines to restore
		// For now, just unfreeze
		p.frozen = false
		p.frozenLines = nil
		p.filteredLines = p.computeFilter()
	}
}
