func (p *Peco) parseHeight() {
	height := p.opts.Height
	if height == "" {
		height = p.config.Height
	}
	if height == "" {
		return
	}

	if strings.HasSuffix(height, "%") {
		pct, err := strconv.ParseFloat(height[:len(height)-1], 64)
		if err == nil {
			p.heightPct = pct / 100.0
			p.heightIsPercent = true
		}
	} else {
		n, err := strconv.Atoi(height)
		if err == nil {
			p.heightLines = n
		}
	}
}

func (p *Peco) readInput() error {
	var reader io.Reader

	if p.opts.File != "" {
		f, err := os.Open(p.opts.File)
		if err != nil {
			return fmt.Errorf("failed to open file: %v", err)
		}
		defer f.Close()
		reader = f
	} else {
		reader = os.Stdin
	}

	scanner := bufio.NewScanner(reader)
	bufSize := p.config.MaxScanBufferSize * 1024
	if bufSize < 64*1024 {
		bufSize = 64 * 1024
	}
	buf := make([]byte, bufSize)
	scanner.Buffer(buf, bufSize)

	if p.opts.Null {
		// NUL-separated mode
		scanner.Split(splitOnNul)
	}

	bufferSize := p.opts.BufferSize

	for scanner.Scan() {
		line := scanner.Text()
		p.lines = append(p.lines, line)
		if bufferSize > 0 && len(p.lines) >= bufferSize {
			// Keep only the last bufferSize lines by sliding window
			p.lines = p.lines[len(p.lines)-bufferSize:]
		}
	}

	return nil
}

// splitOnNul is a custom split function for NUL-separated input
func splitOnNul(data []byte, atEOF bool) (advance int, token []byte, err error) {
	for i, b := range data {
		if b == 0 {
			return i + 1, data[:i], nil
		}
	}
	if atEOF && len(data) > 0 {
		return len(data), data, nil
	}
	return 0, nil, nil
}

func (p *Peco) selectAllAndExit() error {
	for _, line := range p.lines {
		fmt.Println(line)
	}
	return nil
