func (p *Peco) initScreen() (*Terminal, error) {
	term, err := OpenTerminal()
	if err != nil {
		return nil, fmt.Errorf("failed to initialize screen: failed to initialize tcell screen: %v", err)
	}

	// Check TERM environment variable
	termEnv := os.Getenv("TERM")
	if termEnv == "" {
		term.Close()
		return nil, fmt.Errorf("failed to initialize screen: failed to create tcell screen: terminal entry not found: term not set")
	}

	if termEnv == "dumb" {
		term.Close()
		return nil, fmt.Errorf("failed to initialize screen: failed to create tcell screen: terminal not cursor addressable")
	}

	if err := term.MakeRaw(); err != nil {
		term.Close()
		return nil, fmt.Errorf("failed to initialize screen: %v", err)
	}

	p.screen = NewScreen(term, term.File())
	p.inputReader = NewInputReader(term.File())

	return term, nil
}

func (p *Peco) applyInitialFilter() {
	p.filteredLines = p.computeFilter()
}

func (p *Peco) computeFilter() []int {
	query := string(p.query)

	// If query is disabled, return all lines
	if !p.queryEnabled || query == "" {
		result := make([]int, len(p.lines))
		for i := range p.lines {
			result[i] = i
		}
		return result
	}

	var result []int
	for i, line := range p.lines {
		displayLine := line
		if p.config.ANSI {
			displayLine = StripANSI(line)
		}
		if matched, _ := p.filter.Match(displayLine, query); matched {
			result = append(result, i)
		}
	}
	if result == nil {
		result = []int{}
	}
	return result
}

func (p *Peco) mainLoop() error {
	// Set up signal handler for SIGWINCH (terminal resize)
	sigCh := make(chan os.Signal, 1)
	signal.Notify(sigCh, syscall.SIGWINCH)
	defer signal.Stop(sigCh)

	// Set up input channel
	keyCh := make(chan KeyEvent, 10)
	errCh := make(chan error, 1)

	go func() {
		for {
			ev, err := p.inputReader.ReadKey()
			if err != nil {
				errCh <- err
				return
			}
			keyCh <- ev
		}
	}()

	// Initial render
	p.render()

	for {
		select {
		case <-sigCh:
			// Terminal resized
			p.screen.Resize()
			p.adjustPageOffset()
			p.render()

		case err := <-errCh:
			return p.handleExit(false, err)

		case ev := <-keyCh:
			done, err := p.handleKey(ev)
			if done {
				return err
			}
		}
	}
}

func (p *Peco) handleKey(ev KeyEvent) (bool, error) {
	action, found, isPending := p.keymap.LookupAction(ev)

	if isPending {
		// Waiting for more keys in sequence
		return false, nil
	}

	if !found {
		// Check if it's a regular character to type
		if ev.Key == KeyNone && ev.Rune != 0 && ev.Mod == ModNone {
			p.insertChar(ev.Rune)
			p.onQueryChange()
			p.render()
			return false, nil
		}
		if ev.Key == KeyNone && ev.Rune != 0 && ev.Mod == ModAlt {
			// Alt+char - treat as regular input or ignore
			return false, nil
		}
		return false, nil
	}

	return p.executeAction(action)
}

func (p *Peco) executeAction(action Action) (bool, error) {
	// Resolve custom actions
	if p.keymap.customActions != nil {
		if actions, ok := p.keymap.customActions[action]; ok {
			for _, a := range actions {
				done, err := p.executeAction(a)
				if done {
					return done, err
				}
			}
			return false, nil
		}
	}

	switch action {
	case ActionCancel:
		if p.rangeModeActive {
			p.rangeModeActive = false
			p.render()
			return false, nil
		}
		return p.handleExit(false, nil), nil

	case ActionFinish:
		return p.handleExit(true, nil), nil

	case ActionForwardChar:
		if p.queryCursor < len(p.query) {
			p.queryCursor++
			p.render()
		}

	case ActionBackwardChar:
		if p.queryCursor > 0 {
			p.queryCursor--
			p.render()
		}

	case ActionForwardWord:
		p.moveWordForward()
		p.render()

	case ActionBackwardWord:
		p.moveWordBackward()
		p.render()

	case ActionBeginningOfLine:
		p.queryCursor = 0
		p.render()

	case ActionEndOfLine:
		p.queryCursor = len(p.query)
		p.render()

	case ActionEndOfFile:
		if len(p.query) == 0 {
			return p.handleExit(false, nil), nil
		}
		p.deleteForwardChar()
		p.onQueryChange()
		p.render()

	case ActionDeleteForwardChar:
		p.deleteForwardChar()
		p.onQueryChange()
		p.render()

	case ActionDeleteBackwardChar:
		p.deleteBackwardChar()
		p.onQueryChange()
		p.render()

	case ActionDeleteForwardWord:
		p.deleteForwardWord()
		p.onQueryChange()
		p.render()

	case ActionDeleteBackwardWord:
		p.deleteBackwardWord()
		p.onQueryChange()
		p.render()

	case ActionKillEndOfLine:
		if p.queryCursor <= len(p.query) {
			p.query = p.query[:p.queryCursor]
			p.onQueryChange()
			p.render()
		}

	case ActionKillBeginningOfLine:
		if p.queryCursor > 0 {
			p.query = p.query[p.queryCursor:]
			p.queryCursor = 0
			p.onQueryChange()
			p.render()
		}

	case ActionDeleteAll:
		p.query = nil
		p.queryCursor = 0
		p.onQueryChange()
		p.render()

	case ActionSelectUp:
		if p.rangeModeActive {
			p.extendRangeUp()
		} else {
			p.moveUp()
		}
		p.render()

	case ActionSelectDown:
		if p.rangeModeActive {
			p.extendRangeDown()
		} else {
			p.moveDown()
		}
		p.render()

	case ActionScrollPageUp:
		p.pageUp()
		p.render()

	case ActionScrollPageDown:
		p.pageDown()
		p.render()

	case ActionScrollFirstItem:
		p.currentLine = 0
		p.pageOffset = 0
		p.render()

	case ActionScrollLastItem:
		if len(p.filteredLines) > 0 {
			p.currentLine = len(p.filteredLines) - 1
			p.adjustPageOffset()
			p.render()
		}

	case ActionScrollLeft:
		if p.hScrollOffset > 0 {
			p.hScrollOffset -= 10
			if p.hScrollOffset < 0 {
				p.hScrollOffset = 0
			}
			p.render()
		}

	case ActionScrollRight:
		p.hScrollOffset += 10
		p.render()

	case ActionToggleSelection:
		p.toggleCurrentSelection()
		p.render()

	case ActionToggleSelectionAndSelectNext:
		p.toggleCurrentSelection()
		p.moveDown()
		p.render()

	case ActionSelectNone:
		p.selectedLines = make(map[int]bool)
		p.render()

	case ActionSelectAll:
		for _, idx := range p.filteredLines {
			p.selectedLines[idx] = true
		}
		p.render()

	case ActionSelectVisible:
		visibleLines := p.getVisibleLines()
		for _, idx := range visibleLines {
			p.selectedLines[idx] = true
		}
		p.render()

	case ActionInvertSelection:
		newSelected := make(map[int]bool)
		for _, idx := range p.filteredLines {
			if !p.selectedLines[idx] {
				newSelected[idx] = true
			}
		}
		p.selectedLines = newSelected
		p.render()

	case ActionGoToNextSelection:
		p.goToNextSelection(1)
		p.render()

	case ActionGoToPreviousSelection:
		p.goToNextSelection(-1)
		p.render()

	case ActionToggleRangeMode:
		if p.rangeModeActive {
			// Finalize range selection
			p.finalizeRange()
			p.rangeModeActive = false
		} else {
			p.rangeModeActive = true
			p.rangeStart = p.currentLine
		}
		p.render()

	case ActionCancelRangeMode:
		p.rangeModeActive = false
		// Clear range selections? No, just exit range mode
		p.render()

	case ActionRotateFilter:
		p.filterType = (p.filterType + 1) % FilterType(len(FilterNames))
		p.filter = &Filter{Type: p.filterType}
		p.onQueryChange()
		p.render()

	case ActionBackToInitialFilter:
		p.filterType = FilterIgnoreCase
		p.filter = &Filter{Type: p.filterType}
		p.onQueryChange()
		p.render()

	case ActionToggleQuery:
		p.queryEnabled = !p.queryEnabled
		p.onQueryChange()
		p.render()

	case ActionFreezeResults:
		p.freezeResults()
		p.render()

	case ActionUnfreezeResults:
		p.unfreezeResults()
		p.render()

	case ActionZoomIn:
		if !p.zoomedIn {
			p.zoomedIn = true
			p.contextLines = 3
		}
		p.render()

	case ActionZoomOut:
		p.zoomedIn = false
		p.contextLines = 0
		p.render()

	case ActionViewAround:
		p.zoomedIn = !p.zoomedIn
		if p.zoomedIn {
			p.contextLines = 3
		} else {
			p.contextLines = 0
		}
		p.render()

	case ActionToggleSingleKeyJump:
		p.singleKeyJumpMode = !p.singleKeyJumpMode
		p.render()

	case ActionRefreshScreen:
		p.onQueryChange()
		p.render()
	}

	return false, nil
}

func (p *Peco) handleExit(success bool, err error) (bool, error) {
	p.cleanup()

	if !success {
		// User cancelled
		if p.config.OnCancel == "error" {
			os.Exit(1)
		}
		// Default: success exit (exit 0 on cancel)
		return true, nil
	}

	// User finished - output selections
	selections := p.getSelections()

	if p.execCmd != "" {
		return p.executeExec(selections), nil
	}

	p.outputSelections(selections)
	return true, err
}

func (p *Peco) outputSelections(selections []string) {
	if p.opts.PrintQuery {
		fmt.Println(string(p.query))
	}
	for _, line := range selections {
		fmt.Println(line)
	}
}

func (p *Peco) executeExec(selections []string) bool {
	// Write selections to a temp file or pipe
	cmd := exec.Command("/bin/sh", "-c", p.execCmd)

	// Connect stdin with selections
	stdin, err := cmd.StdinPipe()
	if err != nil {
		return false
	}

	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr

	if err := cmd.Start(); err != nil {
		return false
	}

	for _, line := range selections {
		fmt.Fprintln(stdin, line)
	}
	stdin.Close()

	cmd.Wait()

	// Don't exit - return to peco
	return false
}

func (p *Peco) getSelections() []string {
	var result []string

	if len(p.selectedLines) > 0 {
		// Return in original order
		for i, line := range p.lines {
			if p.selectedLines[i] {
				if p.opts.Null {
					// In null mode, extract display part (before NUL) and result part (after NUL)
					result = append(result, line)
				} else {
					result = append(result, line)
				}
			}
		}
	} else {
		// Return current line
		if len(p.filteredLines) > 0 && p.currentLine < len(p.filteredLines) {
			idx := p.filteredLines[p.currentLine]
			result = append(result, p.lines[idx])
		}
	}

	return result
}

func (p *Peco) cleanup() {
