func (p *Peco) clearScreen() {
	if p.heightLines > 0 || p.heightIsPercent {
		// Inline mode: clear the inline area
		h := p.getDisplayHeight()
		fmt.Fprint(p.term.File(), "\033[?25h") // Show cursor
		// Move up h lines and clear
		for i := 0; i < h; i++ {
			fmt.Fprint(p.term.File(), "\033[K\033[A")
		}
		fmt.Fprint(p.term.File(), "\033[K")
	} else {
		// Full screen: just clear and go home
		fmt.Fprint(p.term.File(), "\033[2J\033[H\033[?25h")
	}
