		p.currentLine++
		p.adjustPageOffset()
	}
}

func (p *Peco) pageUp() {
	listH := p.getListHeight()
	if listH <= 0 {
		listH = 1
	}

	p.currentLine -= listH
	if p.currentLine < 0 {
		p.currentLine = 0
	}
	p.pageOffset -= listH
	if p.pageOffset < 0 {
		p.pageOffset = 0
	}
	p.adjustPageOffset()
}

func (p *Peco) pageDown() {
	listH := p.getListHeight()
	if listH <= 0 {
		listH = 1
	}

	p.currentLine += listH
	if p.currentLine >= len(p.filteredLines) {
		if len(p.filteredLines) > 0 {
			p.currentLine = len(p.filteredLines) - 1
		} else {
			p.currentLine = 0
		}
	}
	p.adjustPageOffset()
}

func (p *Peco) extendRangeUp() {
	if p.currentLine > 0 {
		p.currentLine--
		p.adjustPageOffset()
		p.updateRangeSelection()
	}
}

func (p *Peco) extendRangeDown() {
	if p.currentLine < len(p.filteredLines)-1 {
		p.currentLine++
		p.adjustPageOffset()
		p.updateRangeSelection()
	}
}

func (p *Peco) updateRangeSelection() {
	// Clear previous range selections and re-apply
	start := p.rangeStart
	end := p.currentLine
	if start > end {
		start, end = end, start
	}
	for i := start; i <= end && i < len(p.filteredLines); i++ {
		p.selectedLines[p.filteredLines[i]] = true
	}
