func (p *Peco) goToNextSelection(dir int) {
	if len(p.filteredLines) == 0 {
		return
	}

	start := p.currentLine
	n := len(p.filteredLines)

	for i := 1; i < n; i++ {
		next := (start + dir*i + n) % n
		if p.selectedLines[p.filteredLines[next]] {
			p.currentLine = next
			p.adjustPageOffset()
			return
		}
	}
}

func (p *Peco) getVisibleLines() []int {
	listH := p.getListHeight()
	end := p.pageOffset + listH
	if end > len(p.filteredLines) {
		end = len(p.filteredLines)
	}
	var result []int
	for i := p.pageOffset; i < end; i++ {
		result = append(result, p.filteredLines[i])
	}
	return result
