func (p *Peco) moveWordForward() {
	// Skip spaces
	for p.queryCursor < len(p.query) && p.query[p.queryCursor] == ' ' {
		p.queryCursor++
	}
	// Skip non-spaces
	for p.queryCursor < len(p.query) && p.query[p.queryCursor] != ' ' {
		p.queryCursor++
