func (p *Peco) moveWordBackward() {
	if p.queryCursor <= 0 {
		return
	}
	// Skip spaces
	for p.queryCursor > 0 && p.query[p.queryCursor-1] == ' ' {
		p.queryCursor--
	}
	// Skip non-spaces
	for p.queryCursor > 0 && p.query[p.queryCursor-1] != ' ' {
		p.queryCursor--
	}
