	p.query = nil
	p.queryCursor = 0

	// Reload from frozen lines
	if p.frozen {
		// Replace lines with frozen lines and recompute
		savedLines := p.lines
		_ = savedLines
		p.lines = p.frozenLines
		p.filteredLines = p.computeFilter()
