		p.query = nil
		p.queryCursor = 0
		p.onQueryChange()
		p.render()

	case ActionSelectUp:
		if p.rangeModeActive {
			p.extendRangeUp()
		} else {
			p.moveUp()
		}
		p.render()

	case ActionSelectDown:
		if p.rangeModeActive {
			p.extendRangeDown()
		} else {
			p.moveDown()
		}
		p.render()

	case ActionScrollPageUp:
		p.pageUp()
		p.render()

	case ActionScrollPageDown:
		p.pageDown()
		p.render()

	case ActionScrollFirstItem:
		p.currentLine = 0
		p.pageOffset = 0
		p.render()

	case ActionScrollLastItem:
		if len(p.filteredLines) > 0 {
			p.currentLine = len(p.filteredLines) - 1
			p.adjustPageOffset()
