package main

import (
	"fmt"
	"io"
	"strings"
)

// render renders the entire peco interface
func (p *Peco) render() {
	if p.screen == nil {
		return
	}

	w := p.screen.Width()
	displayH := p.getDisplayHeight()
	listH := displayH - 2 // query line + status line
	if listH < 0 {
		listH = 0
	}

	layout := p.config.Layout

	// Inline mode: render at bottom of terminal
	if p.heightLines > 0 || p.heightIsPercent {
		p.renderInline(w, displayH, listH, layout)
		return
	}

	p.screen.Clear()

	switch layout {
	case "bottom-up":
		p.renderBottomUp(w, displayH, listH)
	case "top-down-query-bottom":
		p.renderTopDownQueryBottom(w, displayH, listH)
	default: // top-down
		p.renderTopDown(w, displayH, listH)
	}

	p.screen.Flush()
}

func (p *Peco) renderTopDown(w, displayH, listH int) {
	// Row 0: query line
	p.renderQueryLine(0, w)

	// Rows 1..listH: list
	for i := 0; i < listH; i++ {
		lineIdx := p.pageOffset + i
		p.renderListLine(i+1, lineIdx, w)
	}

	// Last row: status bar
	statusRow := displayH - 1
	if statusRow > 0 {
		p.renderStatusLine(statusRow, w)
	}
}

func (p *Peco) renderBottomUp(w, displayH, listH int) {
	// Rows 0..listH-1: list (in reverse order - item 0 at top but displayed in reverse)
	// In bottom-up mode, the last item in filteredLines is shown at top

	for i := 0; i < listH; i++ {
		// In bottom-up: the visible items are shown in reverse order
		// The "current" item is at the bottom of the list area
		lineIdx := p.pageOffset + (listH - 1 - i)
		p.renderListLine(i, lineIdx, w)
	}

	// Query line
	p.renderQueryLine(listH, w)

	// Status line at bottom
	p.renderStatusLine(displayH-1, w)
}

func (p *Peco) renderTopDownQueryBottom(w, displayH, listH int) {
	// Rows 0..listH-1: list
	for i := 0; i < listH; i++ {
		lineIdx := p.pageOffset + i
		p.renderListLine(i, lineIdx, w)
	}

	// Second to last row: status
	// No - for top-down-query-bottom, query is at bottom, status might be different
	// Actually from observation: list on top, query at bottom (row displayH-1)
	// But the status shows in the query line? Let me check...
	// From the test: only query line visible at bottom, no separate status
	// The status bar is part of query line in this layout

	// Query + status at bottom
	p.renderQueryLine(displayH-1, w)
}

func (p *Peco) renderInline(w, displayH, listH int, layout string) {
	// Save cursor position and render inline
	out := p.term.File()

	// Render to string
	var lines []string

	switch layout {
	case "bottom-up":
		var listLines []string
		for i := 0; i < listH; i++ {
			lineIdx := p.pageOffset + (listH - 1 - i)
			listLines = append(listLines, p.formatListLine(lineIdx, w))
		}
		lines = append(lines, listLines...)
		lines = append(lines, p.formatQueryLine(w))
		lines = append(lines, p.formatStatusLine(w))
	case "top-down-query-bottom":
		var listLines []string
		for i := 0; i < listH; i++ {
			lineIdx := p.pageOffset + i
			listLines = append(listLines, p.formatListLine(lineIdx, w))
		}
		lines = append(lines, p.formatStatusLine(w))
		lines = append(lines, listLines...)
		lines = append(lines, p.formatQueryLine(w))
	default:
		lines = append(lines, p.formatQueryLine(w))
		for i := 0; i < listH; i++ {
			lineIdx := p.pageOffset + i
			lines = append(lines, p.formatListLine(lineIdx, w))
		}
		lines = append(lines, p.formatStatusLine(w))
	}

	// Move up if we've already rendered
	for range lines {
		fmt.Fprint(out, "\033[A\033[K")
	}

	for _, line := range lines {
		fmt.Fprint(out, line+"\r\n")
	}
}

func (p *Peco) renderQueryLine(row, w int) {
	query := string(p.query)
	prompt := p.config.Prompt

	p.screen.ClearLine(row)

	// Render prompt
	x := p.screen.SetString(0, row, prompt+" ", p.styles.Prompt)

	// Render query text
	queryRunes := []rune(query)

	for i, ch := range queryRunes {
		var style Style
		if i == p.queryCursor {
			style = p.styles.QueryCursor
		} else {
			style = p.styles.Query
		}

		if x >= w {
			break
		}
		cw := runeWidth(ch)
		if x+cw > w {
			break
		}
		p.screen.SetCell(x, row, ch, style)
		if cw == 2 && x+1 < w {
			p.screen.SetCell(x+1, row, ' ', style)
		}
		x += cw
	}

	// Cursor at end
	if p.queryCursor == len(queryRunes) && x < w {
		p.screen.SetCell(x, row, ' ', p.styles.QueryCursor)
		x++
	}

	// Fill rest
	p.screen.FillLine(x, row, p.styles.Basic)
}

func (p *Peco) renderStatusLine(row, w int) {
	statusStr := p.formatStatusString()

	p.screen.ClearLine(row)

	// Right-align the status string
	statusLen := stringDisplayWidth(statusStr)
	startX := w - statusLen
	if startX < 0 {
		startX = 0
	}

	// Fill left part with basic style
	p.screen.FillLine(0, row, p.styles.Basic)

	// Render status on the right
	p.screen.SetString(startX, row, statusStr, p.styles.Basic)
}

func (p *Peco) formatStatusString() string {
	filterName := FilterName(p.filterType)
	matchCount := len(p.filteredLines)

	listH := p.getListHeight()
	if listH <= 0 {
		listH = 1
	}

	totalPages := (matchCount + listH - 1) / listH
	if totalPages == 0 {
		totalPages = 1
	}
	currentPage := p.pageOffset/listH + 1

	return fmt.Sprintf("%s [%d (%d/%d)]", filterName, matchCount, currentPage, totalPages)
}

func (p *Peco) renderListLine(row, lineIdx int, w int) {
	p.screen.ClearLine(row)

	if lineIdx < 0 || lineIdx >= len(p.filteredLines) {
		p.screen.FillLine(0, row, p.styles.Basic)
		return
	}

	filtIdx := p.filteredLines[lineIdx]
	line := p.lines[filtIdx]

	isSelected := filtIdx == p.filteredLines[p.currentLine]
	isSaved := p.selectedLines[filtIdx]

	if isSaved {
		p.renderLineWithStyle(row, line, p.styles.SavedSelection, w, lineIdx)
	} else if isSelected {
		p.renderLineWithStyle(row, line, p.styles.Selected, w, lineIdx)
	} else {
		p.renderLineWithMatches(row, line, filtIdx, w, lineIdx)
	}
}

func (p *Peco) renderLineWithStyle(row int, line string, style Style, w int, lineIdx int) {
	displayLine := line
	if p.config.ANSI {
		displayLine = StripANSI(line)
	}

	// Handle horizontal scrolling
	if p.hScrollOffset > 0 {
		displayLine = scrollString(displayLine, p.hScrollOffset)
	}

	// Handle selection prefix
	if p.config.SelectionPrefix != "" && p.selectedLines[p.filteredLines[lineIdx]] {
		p.screen.SetString(0, row, p.config.SelectionPrefix, style)
		prefixW := stringDisplayWidth(p.config.SelectionPrefix)
		p.screen.SetString(prefixW, row, displayLine, style)
