		x := p.screen.SetString(0, row, scrolled, basicStyle)
		p.screen.FillLine(x, row, basicStyle)
		return
	}

	// Get match ranges (on the original unscrolled line)
	_, ranges := p.filter.Match(displayLine, query)

	if len(ranges) == 0 {
		x := p.screen.SetString(0, row, scrolled, basicStyle)
		p.screen.FillLine(x, row, basicStyle)
		return
	}

