	return len(s)
}

func scrollString(s string, offset int) string {
	if offset <= 0 {
		return s
	}

	w := 0
	for i, r := range s {
		rw := runeWidth(r)
		if w+rw > offset {
			// Partial wide char
			return s[i:]
		}
		w += rw
		if w >= offset {
			// Find next rune
			nextI := i
			for range s[nextI:] {
				nextI++
				break
			}
