func (p *Peco) formatStatusLine(w int) string {
	return p.formatStatusString()
}

// formatListLine returns a string for a list line (used in inline mode)
func (p *Peco) formatListLine(lineIdx int, w int) string {
	if lineIdx < 0 || lineIdx >= len(p.filteredLines) {
		return ""
	}
	filtIdx := p.filteredLines[lineIdx]
	return p.lines[filtIdx]
}

// screenFlushToWriter writes the full screen content to the given writer
// Used for inline mode
func (p *Peco) screenFlushToWriter(out io.Writer) {
	w := p.screen.Width()
	h := p.screen.Height()

	for y := 0; y < h; y++ {
		var line strings.Builder
		for x := 0; x < w; x++ {
			cell := p.screen.cells[y][x]
			ch := cell.Ch
			if ch == 0 {
				ch = ' '
			}
			line.WriteRune(ch)
		}
		if y < h-1 {
			fmt.Fprintln(out, line.String())
		} else {
			fmt.Fprint(out, line.String())
		}
	}
}
GOEOF

