package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"
)

func parseOptions(args []string) (*Options, error) {
	opts := &Options{
		InitialIndex: 0,
		BufferSize:   0,
	}

	i := 0
	for i < len(args) {
		arg := args[i]

		switch {
		case arg == "-h" || arg == "--help":
			opts.Help = true
			return opts, nil

		case arg == "--version":
			opts.Version = true
			return opts, nil

		case arg == "--query":
			if i+1 >= len(args) {
				return nil, fmt.Errorf("--query requires an argument")
			}
			i++
			opts.Query = args[i]
			opts.HasQuery = true

		case strings.HasPrefix(arg, "--query="):
			opts.Query = arg[len("--query="):]
			opts.HasQuery = true

		case arg == "--rcfile":
			if i+1 >= len(args) {
				return nil, fmt.Errorf("--rcfile requires an argument")
			}
			i++
			opts.RcFile = args[i]

		case strings.HasPrefix(arg, "--rcfile="):
			opts.RcFile = arg[len("--rcfile="):]

		case arg == "-b" || arg == "--buffer-size":
			if i+1 >= len(args) {
				return nil, fmt.Errorf("--buffer-size requires an argument")
			}
			i++
			n, err := strconv.Atoi(args[i])
			if err != nil {
				return nil, fmt.Errorf("invalid buffer-size: %v", err)
			}
			opts.BufferSize = n

		case strings.HasPrefix(arg, "--buffer-size="):
			n, err := strconv.Atoi(arg[len("--buffer-size="):])
			if err != nil {
				return nil, fmt.Errorf("invalid buffer-size: %v", err)
			}
			opts.BufferSize = n

		case strings.HasPrefix(arg, "-b="):
			n, err := strconv.Atoi(arg[3:])
			if err != nil {
				return nil, fmt.Errorf("invalid buffer-size: %v", err)
			}
			opts.BufferSize = n

		case arg == "--null":
			opts.Null = true

		case arg == "--initial-index":
			if i+1 >= len(args) {
				return nil, fmt.Errorf("--initial-index requires an argument")
			}
			i++
			n, err := strconv.Atoi(args[i])
			if err != nil {
				return nil, fmt.Errorf("invalid initial-index: %v", err)
			}
			opts.InitialIndex = n

		case strings.HasPrefix(arg, "--initial-index="):
			n, err := strconv.Atoi(arg[len("--initial-index="):])
			if err != nil {
