package main

import (
	"fmt"
	"io"
	"strings"
)

// render renders the entire peco interface
func (p *Peco) render() {
	if p.screen == nil {
		return
	}

	w := p.screen.Width()
	h := p.screen.Height()
	displayH := p.getDisplayHeight()
	if displayH > h {
		displayH = h
	}

	// List height = total height - 1 (for combined query+status line)
	listH := displayH - 1
	if listH < 0 {
		listH = 0
	}

	layout := p.config.Layout

	p.screen.Clear()

	switch layout {
	case "bottom-up":
		p.renderBottomUp(w, displayH, listH)
	case "top-down-query-bottom":
		p.renderTopDownQueryBottom(w, displayH, listH)
	default: // top-down
		p.renderTopDown(w, displayH, listH)
	}

	p.screen.Flush()
}

func (p *Peco) renderTopDown(w, displayH, listH int) {
	// Row 0: combined query + status line
	p.renderQueryStatusLine(0, w)

	// Rows 1..listH: list items
	for i := 0; i < listH; i++ {
		lineIdx := p.pageOffset + i
		p.renderListLine(i+1, lineIdx, w)
	}
}

func (p *Peco) renderBottomUp(w, displayH, listH int) {
	// Rows 0..listH-1: list items (in reverse order)
	for i := 0; i < listH; i++ {
		// In bottom-up mode, items are displayed in reverse order
		// Item at currentLine is shown closest to the query line
		// The bottom-most visible item in the list is at row listH-1
		lineIdx := p.pageOffset + (listH - 1 - i)
		p.renderListLine(i, lineIdx, w)
	}

	// Last row: combined query + status line
	p.renderQueryStatusLine(listH, w)
}

func (p *Peco) renderTopDownQueryBottom(w, displayH, listH int) {
	// Rows 0..listH-1: list items
	for i := 0; i < listH; i++ {
		lineIdx := p.pageOffset + i
		p.renderListLine(i, lineIdx, w)
	}

	// Last row: combined query + status line
	p.renderQueryStatusLine(listH, w)
}

// renderQueryStatusLine renders the combined query and status on one row
func (p *Peco) renderQueryStatusLine(row, w int) {
	prompt := p.config.Prompt
	statusStr := p.formatStatusString()
	statusLen := stringDisplayWidth(statusStr)

	// Clear line first
	p.screen.ClearLine(row)
	p.screen.FillLine(0, row, p.styles.Basic)

	// Render prompt
	x := p.screen.SetString(0, row, prompt+" ", p.styles.Prompt)

	// Available space for query (leave room for status)
	statusStart := w - statusLen
	if statusStart < x {
		statusStart = x
	}

	// Render query text
	queryRunes := []rune(string(p.query))

	// Calculate visible portion of query (may need to scroll if cursor is past view)
	queryDisplayWidth := statusStart - x
	if queryDisplayWidth < 0 {
		queryDisplayWidth = 0
	}

	// Find start of query display based on cursor position
	queryStartIdx := p.computeQueryScroll(queryRunes, queryDisplayWidth)

	// Render query characters
	qx := x
	for i := queryStartIdx; i <= len(queryRunes); i++ {
		if i == len(queryRunes) {
			// End of query - render cursor
			if qx < statusStart {
				var style Style
				if i == p.queryCursor {
					style = p.styles.QueryCursor
				} else {
					style = p.styles.Basic
				}
				p.screen.SetCell(qx, row, ' ', style)
				qx++
			}
			break
		}

		ch := queryRunes[i]
		cw := runeWidth(ch)

		if qx+cw > statusStart {
			break
		}

		var style Style
		if i == p.queryCursor {
			style = p.styles.QueryCursor
		} else {
			style = p.styles.Query
		}

		p.screen.SetCell(qx, row, ch, style)
		if cw == 2 && qx+1 < statusStart {
			p.screen.SetCell(qx+1, row, ' ', style)
		}
		qx += cw
	}

	// Fill gap between query and status
	for i := qx; i < statusStart; i++ {
		p.screen.SetCell(i, row, ' ', p.styles.Basic)
	}

	// Render status text (right-aligned)
	if statusStart <= w {
		p.screen.SetString(statusStart, row, statusStr, p.styles.Basic)
	}
}

// computeQueryScroll computes the starting index in the query to display
// given the available display width for the query area
func (p *Peco) computeQueryScroll(query []rune, availWidth int) int {
	if len(query) == 0 || availWidth <= 0 {
		return 0
	}

	// If cursor position's display position fits, start from 0
	// Otherwise scroll so cursor is visible

	// First try starting from 0
	width := 0
	for i, r := range query {
		if i == p.queryCursor {
			// Cursor fits
			return 0
		}
		width += runeWidth(r)
		if width >= availWidth {
			break
		}
	}

	if p.queryCursor <= len(query) {
		// Check if everything fits
		totalWidth := 0
		for _, r := range query {
			totalWidth += runeWidth(r)
		}
		if totalWidth <= availWidth {
			return 0
		}
	}

	// Need to scroll - show cursor in view
	// Find start such that cursor fits in availWidth
	cursorPos := p.queryCursor

	// Calculate display width up to cursor
	widthToCursor := 0
	for i := 0; i < cursorPos && i < len(query); i++ {
		widthToCursor += runeWidth(query[i])
	}

	if widthToCursor < availWidth {
		return 0
	}

	// Scroll back from cursor
	targetStart := cursorPos
	w := 0
	for targetStart > 0 {
		targetStart--
		w += runeWidth(query[targetStart])
		if w >= availWidth-1 {
			targetStart++
			break
		}
	}
	return targetStart
}

func (p *Peco) renderStatusString() string {
	return p.formatStatusString()
}

func (p *Peco) formatStatusString() string {
	filterName := FilterName(p.filterType)
	matchCount := len(p.filteredLines)

	listH := p.getListHeight()
	if listH <= 0 {
		listH = 1
	}

	totalPages := (matchCount + listH - 1) / listH
	if totalPages == 0 {
		totalPages = 1
	}
	currentPage := p.pageOffset/listH + 1

	return fmt.Sprintf("%s [%d (%d/%d)]", filterName, matchCount, currentPage, totalPages)
}

func (p *Peco) renderListLine(row, lineIdx int, w int) {
	p.screen.ClearLine(row)

	if lineIdx < 0 || lineIdx >= len(p.filteredLines) {
		p.screen.FillLine(0, row, p.styles.Basic)
		return
	}

	filtIdx := p.filteredLines[lineIdx]
	line := p.lines[filtIdx]

	isSelected := lineIdx == p.currentLine
	isSaved := p.selectedLines[filtIdx]

	if isSaved {
		p.renderLineWithStyle(row, line, filtIdx, p.styles.SavedSelection, w, lineIdx)
	} else if isSelected {
		p.renderLineWithStyle(row, line, filtIdx, p.styles.Selected, w, lineIdx)
	} else {
		p.renderLineWithMatches(row, line, filtIdx, w)
	}
}

func (p *Peco) renderLineWithStyle(row int, line string, filtIdx int, style Style, w int, lineIdx int) {
	displayLine := line
	if p.config.ANSI {
		displayLine = StripANSI(line)
	}

	// Handle horizontal scrolling
	if p.hScrollOffset > 0 {
		displayLine = scrollString(displayLine, p.hScrollOffset)
	}

	// Handle selection prefix
	selPrefix := p.config.SelectionPrefix
	if selPrefix != "" && p.selectedLines[filtIdx] {
		prefixW := stringDisplayWidth(selPrefix)
		p.screen.SetString(0, row, selPrefix, style)
		x := p.screen.SetString(prefixW, row, displayLine, style)
		p.screen.FillLine(x, row, style)
	} else {
		x := p.screen.SetString(0, row, displayLine, style)
		p.screen.FillLine(x, row, style)
	}
}

func (p *Peco) renderLineWithMatches(row int, line string, filtIdx int, w int) {
	query := string(p.query)

	displayLine := line
	if p.config.ANSI {
		displayLine = StripANSI(line)
	}

	// Handle horizontal scrolling
	scrolled := displayLine
	if p.hScrollOffset > 0 {
		scrolled = scrollString(displayLine, p.hScrollOffset)
	}

	basicStyle := p.styles.Basic

	if query == "" || !p.queryEnabled {
		x := p.screen.SetString(0, row, scrolled, basicStyle)
		p.screen.FillLine(x, row, basicStyle)
		return
	}

	// Get match ranges (on the original unscrolled line)
	_, ranges := p.filter.Match(displayLine, query)

	if len(ranges) == 0 {
		x := p.screen.SetString(0, row, scrolled, basicStyle)
		p.screen.FillLine(x, row, basicStyle)
		return
	}

	// Adjust ranges for horizontal scrolling
	adjustedRanges := ranges
	if p.hScrollOffset > 0 {
		adjustedRanges = adjustRangesForScroll(ranges, displayLine, p.hScrollOffset)
	}

	// Render with highlighted matches
	runes := []rune(scrolled)
	x := 0

	for ri, ch := range runes {
		if x >= w {
			break
		}

		bytePos := runeIndexToByteIndex(scrolled, ri)
		isMatch := isInRanges(bytePos, adjustedRanges)

		var style Style
		if isMatch {
			style = p.styles.Matched
		} else {
			style = basicStyle
		}

		cw := runeWidth(ch)
		if x+cw > w {
			break
		}
		p.screen.SetCell(x, row, ch, style)
		if cw == 2 && x+1 < w {
			p.screen.SetCell(x+1, row, ' ', style)
		}
		x += cw
	}

	p.screen.FillLine(x, row, basicStyle)
}

func isInRanges(pos int, ranges [][2]int) bool {
	for _, r := range ranges {
		if pos >= r[0] && pos < r[1] {
			return true
		}
	}
	return false
}

func runeIndexToByteIndex(s string, runeIdx int) int {
	i := 0
	for ri, r := range s {
		if i == runeIdx {
			return ri
		}
		i++
		_ = r
	}
	return len(s)
}

func adjustRangesForScroll(ranges [][2]int, line string, scrollOffset int) [][2]int {
	// Find byte offset corresponding to scrollOffset display chars
	scrollBytes := displayWidthToByteOffset(line, scrollOffset)

	var result [][2]int
	for _, r := range ranges {
		start := r[0] - scrollBytes
		end := r[1] - scrollBytes
		if end <= 0 {
			continue
		}
		if start < 0 {
			start = 0
		}
		result = append(result, [2]int{start, end})
	}
	return result
}

func displayWidthToByteOffset(s string, displayWidth int) int {
	w := 0
	for i, r := range s {
		if w >= displayWidth {
			return i
		}
		w += runeWidth(r)
	}
	return len(s)
}

func scrollString(s string, offset int) string {
	if offset <= 0 {
		return s
	}

	w := 0
	for i, r := range s {
		rw := runeWidth(r)
		w += rw
		if w >= offset {
			// Return from the next character
			nextI := i + len(string(r))
			return s[nextI:]
		}
	}
	return ""
}

// formatQueryLine returns a string for the query line (used in inline mode)
func (p *Peco) formatQueryLine(w int) string {
	_ = w
	prompt := p.config.Prompt
	query := string(p.query)
	return fmt.Sprintf("%s %s", prompt, query)
}

// formatStatusLine returns a string for the status line (used in inline mode)
func (p *Peco) formatStatusLine(w int) string {
	return p.formatStatusString()
}

// formatListLine returns a string for a list line (used in inline mode)
func (p *Peco) formatListLine(lineIdx int, w int) string {
	if lineIdx < 0 || lineIdx >= len(p.filteredLines) {
		return ""
	}
	filtIdx := p.filteredLines[lineIdx]
	return p.lines[filtIdx]
}

// screenFlushToWriter writes the full screen content to the given writer
func (p *Peco) screenFlushToWriter(out io.Writer) {
	w := p.screen.Width()
	h := p.screen.Height()

	for y := 0; y < h; y++ {
		var line strings.Builder
		for x := 0; x < w; x++ {
			cell := p.screen.cells[y][x]
			ch := cell.Ch
			if ch == 0 {
				ch = ' '
			}
			line.WriteRune(ch)
		}
		if y < h-1 {
			fmt.Fprintln(out, line.String())
		} else {
