	if len(query) == 0 || availWidth <= 0 {
		return 0
	}

	// If cursor position's display position fits, start from 0
	// Otherwise scroll so cursor is visible

	// First try starting from 0
	width := 0
	for i, r := range query {
		if i == p.queryCursor {
