func (p *Peco) renderLineWithMatches(row int, line string, filtIdx int, w int) {
	query := string(p.query)

	displayLine := line
	if p.config.ANSI {
		displayLine = StripANSI(line)
	}

	// Handle horizontal scrolling
	scrolled := displayLine
	if p.hScrollOffset > 0 {
		scrolled = scrollString(displayLine, p.hScrollOffset)
	}

	basicStyle := p.styles.Basic

	if query == "" || !p.queryEnabled {
		x := p.screen.SetString(0, row, scrolled, basicStyle)
		p.screen.FillLine(x, row, basicStyle)
		return
	}

	// Get match ranges (on the original unscrolled line)
	_, ranges := p.filter.Match(displayLine, query)

	if len(ranges) == 0 {
		x := p.screen.SetString(0, row, scrolled, basicStyle)
		p.screen.FillLine(x, row, basicStyle)
		return
	}

	// Adjust ranges for horizontal scrolling
	adjustedRanges := ranges
	if p.hScrollOffset > 0 {
		adjustedRanges = adjustRangesForScroll(ranges, displayLine, p.hScrollOffset)
	}

	// Render with highlighted matches
	runes := []rune(scrolled)
	x := 0

	for ri, ch := range runes {
		if x >= w {
			break
		}

		bytePos := runeIndexToByteIndex(scrolled, ri)
		isMatch := isInRanges(bytePos, adjustedRanges)

		var style Style
		if isMatch {
			style = p.styles.Matched
		} else {
			style = basicStyle
		}

		cw := runeWidth(ch)
		if x+cw > w {
			break
		}
		p.screen.SetCell(x, row, ch, style)
		if cw == 2 && x+1 < w {
			p.screen.SetCell(x+1, row, ' ', style)
		}
		x += cw
	}

	p.screen.FillLine(x, row, basicStyle)
}

func isInRanges(pos int, ranges [][2]int) bool {
	for _, r := range ranges {
		if pos >= r[0] && pos < r[1] {
			return true
		}
	}
	return false
}

func runeIndexToByteIndex(s string, runeIdx int) int {
	i := 0
	for ri, r := range s {
		if i == runeIdx {
			return ri
		}
		i++
		_ = r
	}
	return len(s)
}

func adjustRangesForScroll(ranges [][2]int, line string, scrollOffset int) [][2]int {
	// Find byte offset corresponding to scrollOffset display chars
	scrollBytes := displayWidthToByteOffset(line, scrollOffset)

	var result [][2]int
	for _, r := range ranges {
		start := r[0] - scrollBytes
		end := r[1] - scrollBytes
		if end <= 0 {
			continue
		}
		if start < 0 {
			start = 0
		}
		result = append(result, [2]int{start, end})
	}
	return result
}

func displayWidthToByteOffset(s string, displayWidth int) int {
	w := 0
	for i, r := range s {
		if w >= displayWidth {
			return i
		}
		w += runeWidth(r)
	}
	return len(s)
}

func scrollString(s string, offset int) string {
	if offset <= 0 {
		return s
	}

	w := 0
	for i, r := range s {
		rw := runeWidth(r)
		w += rw
		if w >= offset {
			// Return from the next character
			nextI := i + len(string(r))
			return s[nextI:]
		}
	}
	return ""
}

// formatQueryLine returns a string for the query line (used in inline mode)
func (p *Peco) formatQueryLine(w int) string {
	_ = w
	prompt := p.config.Prompt
	query := string(p.query)
	return fmt.Sprintf("%s %s", prompt, query)
}

// formatStatusLine returns a string for the status line (used in inline mode)
func (p *Peco) formatStatusLine(w int) string {
	return p.formatStatusString()
}

// formatListLine returns a string for a list line (used in inline mode)
func (p *Peco) formatListLine(lineIdx int, w int) string {
	if lineIdx < 0 || lineIdx >= len(p.filteredLines) {
		return ""
	}
	filtIdx := p.filteredLines[lineIdx]
	return p.lines[filtIdx]
}

// screenFlushToWriter writes the full screen content to the given writer
func (p *Peco) screenFlushToWriter(out io.Writer) {
	w := p.screen.Width()
	h := p.screen.Height()

	for y := 0; y < h; y++ {
		var line strings.Builder
		for x := 0; x < w; x++ {
			cell := p.screen.cells[y][x]
			ch := cell.Ch
			if ch == 0 {
				ch = ' '
			}
			line.WriteRune(ch)
		}
		if y < h-1 {
			fmt.Fprintln(out, line.String())
		} else {
			fmt.Fprint(out, line.String())
		}
	}
}

// renderInline renders in inline mode (--height)
func (p *Peco) renderInline(w, displayH, listH int, layout string) {
	out := p.term.File()

	var lines []string

	switch layout {
	case "bottom-up":
		var listLines []string
		for i := 0; i < listH; i++ {
			lineIdx := p.pageOffset + (listH - 1 - i)
			listLines = append(listLines, p.formatListLine(lineIdx, w))
		}
		lines = append(lines, listLines...)
		lines = append(lines, p.formatQueryLine(w))
	case "top-down-query-bottom":
		for i := 0; i < listH; i++ {
			lineIdx := p.pageOffset + i
			lines = append(lines, p.formatListLine(lineIdx, w))
		}
		lines = append(lines, p.formatQueryLine(w))
	default:
		lines = append(lines, p.formatQueryLine(w))
		for i := 0; i < listH; i++ {
			lineIdx := p.pageOffset + i
			lines = append(lines, p.formatListLine(lineIdx, w))
		}
	}

	// Move up if we've already rendered
	for range lines {
		fmt.Fprint(out, "\033[A\033[K")
	}

	for _, line := range lines {
		fmt.Fprint(out, line+"\r\n")
	}
}
