		p.renderListLine(i, lineIdx, w)
	}

	// Last row: combined query + status line
	p.renderQueryStatusLine(listH, w)
}

// renderQueryStatusLine renders the combined query and status on one row
func (p *Peco) renderQueryStatusLine(row, w int) {
	prompt := p.config.Prompt
	statusStr := p.formatStatusString()
	statusLen := stringDisplayWidth(statusStr)

	// Clear line first
	p.screen.ClearLine(row)
	p.screen.FillLine(0, row, p.styles.Basic)

	// Render prompt
	x := p.screen.SetString(0, row, prompt+" ", p.styles.Prompt)

	// Available space for query (leave room for status)
	statusStart := w - statusLen
	if statusStart < x {
		statusStart = x
	}

	// Render query text
	queryRunes := []rune(string(p.query))

	// Calculate visible portion of query (may need to scroll if cursor is past view)
	queryDisplayWidth := statusStart - x
	if queryDisplayWidth < 0 {
		queryDisplayWidth = 0
	}

	// Find start of query display based on cursor position
	queryStartIdx := p.computeQueryScroll(queryRunes, queryDisplayWidth)

	// Render query characters
	qx := x
	for i := queryStartIdx; i <= len(queryRunes); i++ {
		if i == len(queryRunes) {
			// End of query - render cursor
			if qx < statusStart {
				var style Style
				if i == p.queryCursor {
					style = p.styles.QueryCursor
				} else {
					style = p.styles.Basic
				}
				p.screen.SetCell(qx, row, ' ', style)
				qx++
			}
			break
		}

		ch := queryRunes[i]
		cw := runeWidth(ch)

		if qx+cw > statusStart {
			break
		}

		var style Style
		if i == p.queryCursor {
			style = p.styles.QueryCursor
		} else {
			style = p.styles.Query
		}

		p.screen.SetCell(qx, row, ch, style)
		if cw == 2 && qx+1 < statusStart {
			p.screen.SetCell(qx+1, row, ' ', style)
		}
		qx += cw
	}

	// Fill gap between query and status
	for i := qx; i < statusStart; i++ {
		p.screen.SetCell(i, row, ' ', p.styles.Basic)
	}

	// Render status text (right-aligned)
	if statusStart <= w {
		p.screen.SetString(statusStart, row, statusStr, p.styles.Basic)
	}
}

// computeQueryScroll computes the starting index in the query to display
// given the available display width for the query area
func (p *Peco) computeQueryScroll(query []rune, availWidth int) int {
	if len(query) == 0 || availWidth <= 0 {
		return 0
	}

	// If cursor position's display position fits, start from 0
	// Otherwise scroll so cursor is visible

	// First try starting from 0
	width := 0
	for i, r := range query {
		if i == p.queryCursor {
			// Cursor fits
			return 0
		}
		width += runeWidth(r)
		if width >= availWidth {
			break
		}
	}

	if p.queryCursor <= len(query) {
		// Check if everything fits
		totalWidth := 0
		for _, r := range query {
			totalWidth += runeWidth(r)
		}
		if totalWidth <= availWidth {
			return 0
		}
	}

	// Need to scroll - show cursor in view
	// Find start such that cursor fits in availWidth
	cursorPos := p.queryCursor

	// Calculate display width up to cursor
	widthToCursor := 0
	for i := 0; i < cursorPos && i < len(query); i++ {
		widthToCursor += runeWidth(query[i])
	}

	if widthToCursor < availWidth {
		return 0
	}

	// Scroll back from cursor
	targetStart := cursorPos
	w := 0
	for targetStart > 0 {
		targetStart--
		w += runeWidth(query[targetStart])
		if w >= availWidth-1 {
			targetStart++
			break
		}
	}
	return targetStart
}

