		p.screen.FillLine(0, row, p.styles.Basic)
		return
	}

	filtIdx := p.filteredLines[lineIdx]
	line := p.lines[filtIdx]

	isSelected := lineIdx == p.currentLine
	isSaved := p.selectedLines[filtIdx]

	if isSaved {
		p.renderLineWithStyle(row, line, filtIdx, p.styles.SavedSelection, w, lineIdx)
	} else if isSelected {
		p.renderLineWithStyle(row, line, filtIdx, p.styles.Selected, w, lineIdx)
	} else {
