	if p.hScrollOffset > 0 {
		displayLine = scrollString(displayLine, p.hScrollOffset)
	}

	// Handle selection prefix
	selPrefix := p.config.SelectionPrefix
	if selPrefix != "" && p.selectedLines[filtIdx] {
		prefixW := stringDisplayWidth(selPrefix)
		p.screen.SetString(0, row, selPrefix, style)
		x := p.screen.SetString(prefixW, row, displayLine, style)
		p.screen.FillLine(x, row, style)
	} else {
